const results = await runs.all([
  {
    key: 'endpoint-policy',
    agent: 'scout',
    task: 'Repository: /root/hevy-mcp at origin/main snapshot 2443cad. Read issue 941 target architecture and inspect the current endpoint/error/retry/observability code in packages/hevy-client, packages/core, packages/node, and packages/operations. Do not modify files. Recommend a concrete, bounded first implementation slice that honors issue 941: one canonical endpoint identity owner, distinct retry/expected-absence/diagnostic-safety/metric-identity facts, unknown endpoints fail closed, and no runtime-specific dependencies in neutral packages. Include exact files/symbols, migration steps, tests to add/update, Changeset cascade, and risks. Do not implement the full roadmap or a universal runtime base class.'
  },
  {
    key: 'operations',
    agent: 'scout',
    task: 'Repository: /root/hevy-mcp at origin/main snapshot 2443cad. Read issue 941 and inspect packages/operations, packages/core tools, and packages/cli commands. Do not modify files. Map the current shared operations seam and identify the smallest end-to-end vertical slice that can be implemented now without combining the full migration. Include exact duplicated workflows, proposed typed operations interface, tests, package boundaries, and Changeset implications. Explicitly flag anything that should remain deferred.'
  },
  {
    key: 'runtime-hosts',
    agent: 'reviewer',
    task: 'Repository: /root/hevy-mcp at origin/main snapshot 2443cad. Read issue 941 and inspect Node and Worker composition/lifecycle/observation seams. Do not modify files. Assess whether the requested architecture can safely be implemented in one PR now, and propose the narrowest high-value code slice with concrete file/symbol references and validation. Preserve independent Node stdio, stateful Node HTTP, and stateless Worker HTTP/OAuth; reject a universal base class.'
  }
]);
return results.map((result) => ({ key: result.key, output: result.output }));

