		return ErrorType.NOT_FOUND;
	}
	if (
		nameLower.includes("api") ||
		classificationText.includes("api") ||
		classificationText.includes("server error") ||
		classificationText.includes("500")
	) {
		return ErrorType.API_ERROR;
	}
	return ErrorType.UNKNOWN_ERROR;
}

function classifyError(error: unknown): SafeErrorCategory {
	if (isHevyHttpError(error)) return "HevyHttpError";
	if (error instanceof TypeError) return "TypeError";
	if (error instanceof RangeError) return "RangeError";
	if (error instanceof ReferenceError) return "ReferenceError";
	if (error instanceof SyntaxError) return "SyntaxError";
	if (error instanceof URIError) return "URIError";
	if (error instanceof EvalError) return "EvalError";
	if (error instanceof AggregateError) return "AggregateError";
	if (typeof DOMException !== "undefined" && error instanceof DOMException) {
		return "DOMException";
	}
	if (error instanceof Error) return "Error";
	return "UnknownError";
}

function getSafeCode(error: unknown): string | undefined {
	const abortTimeout = getAbortTimeoutErrorMetadata(error);
	if (abortTimeout) return abortTimeout.code;
	if (!error || typeof error !== "object" || !("code" in error)) {
		return undefined;
	}
	const code = error.code;
	return typeof code === "string" && SAFE_ERROR_CODES.has(code)
		? code
		: undefined;
}

function getSafeMethod(error: unknown): string | undefined {
	if (!isHevyHttpError(error)) return undefined;
	const method = error.method.toUpperCase();
	return SAFE_HTTP_METHODS.has(method) ? method : undefined;
}

function getSafeEndpoint(error: unknown): string | undefined {
	if (!isHevyHttpError(error)) return undefined;
	return SAFE_ENDPOINTS.has(error.endpoint) ? error.endpoint : undefined;
}

function getExecutionFields(
	error: unknown,
): Pick<
	SafeErrorDiagnostic,
	"phase" | "operation_safety" | "commit_state" | "safe_to_retry" | "outcome"
> {
	if (!isHevyHttpError(error)) {
		const abortTimeout = getAbortTimeoutErrorMetadata(error);
		if (abortTimeout) {
			return {
				commit_state: "unknown",
				safe_to_retry: false,
				outcome: abortTimeout.outcome,
			};
		}
		return {};
	}
	return {
		...(error.phase ? { phase: error.phase } : {}),
		...(error.operation_safety
			? { operation_safety: error.operation_safety }
			: {}),
		...(error.commit_state ? { commit_state: error.commit_state } : {}),
		...(typeof error.safe_to_retry === "boolean"
			? { safe_to_retry: error.safe_to_retry }
			: {}),
		...(error.outcome ? { outcome: error.outcome } : {}),
	};
}

function parseSafeStackFrames(error: unknown): SafeStackFrame[] | undefined {
	if (!(error instanceof Error) || typeof error.stack !== "string") {
		return undefined;
	}

	const frames: SafeStackFrame[] = [];
	for (const frameLine of error.stack.split(/\r?\n/).slice(1)) {
		const match =
			/^\s{4}at (?:[^()\r\n]+ \()?([^()\s\r\n]+):(\d+):(\d+)\)?$/.exec(
				frameLine,
			);
		if (!match) continue;
		const [, rawSource, rawLine, rawColumn] = match;
		if (!rawSource || !rawLine || !rawColumn) continue;
		if (
			rawSource.includes("?") ||
			rawSource.includes("#") ||
			(!rawSource.startsWith("/") && !rawSource.startsWith("file:///")) ||
			!rawSource.includes(PROJECT_PATH_MARKER)
		) {
			continue;
		}
		const source = SAFE_SOURCE_SUFFIXES.find(([suffix]) =>
			rawSource.endsWith(suffix),
		)?.[1];
		if (!source) continue;
		const line = Number(rawLine);
		const column = Number(rawColumn);
		if (
			!Number.isSafeInteger(line) ||
			!Number.isSafeInteger(column) ||
			line < 1 ||
			column < 1 ||
			line > MAX_STACK_POSITION ||
			column > MAX_STACK_POSITION
		) {
			continue;
		}
		frames.push({ source, line, column });
		if (frames.length === 3) break;
	}
	return frames.length > 0 ? frames : undefined;
}

/** Build bounded diagnostic metadata with no raw messages, payloads, or URLs. */
export function createSafeErrorDiagnostic(error: unknown): SafeErrorDiagnostic {
	try {
		const diagnostic: SafeErrorDiagnostic = { category: classifyError(error) };
		const code = getSafeCode(error);
		const status = extractErrorStatus(error);
		const method = getSafeMethod(error);
		const endpoint = getSafeEndpoint(error);
		const frames = parseSafeStackFrames(error);
		if (code) diagnostic.code = code;
		if (status !== undefined) diagnostic.status = status;
		if (method) diagnostic.method = method;
		if (endpoint) diagnostic.endpoint = endpoint;
		if (frames) diagnostic.frames = frames;
		Object.assign(diagnostic, getExecutionFields(error));
		return diagnostic;
	} catch {
		return { category: "UnknownError" };
	}
}

export interface ErrorPolicyResult {
	type: ErrorType;
	message: string;
	diagnostic: SafeErrorDiagnostic;
}

/** Resolve all bounded policy outputs used by MCP, telemetry, and reporting adapters. */
export function resolveErrorPolicy(
	error: unknown,
	defaultMessage: string,
	notInitializedMessage?: string,
): ErrorPolicyResult {
	const diagnostic = createSafeErrorDiagnostic(error);
	const mappedMessage = getStatusErrorMessage(diagnostic.status);
	let message =
		mappedMessage ??
		(diagnostic.status !== undefined
			? `Hevy API request failed (HTTP ${diagnostic.status}).`
			: defaultMessage);
	let isNotInitialized = false;
	try {
		isNotInitialized =
			Boolean(notInitializedMessage) &&
			error instanceof Error &&
			error.message === notInitializedMessage;
	} catch {
		isNotInitialized = false;
	}
	if (isNotInitialized) {
		message = notInitializedMessage ?? defaultMessage;
	} else if (isRetryExhausted(error)) {
		message = getRetryExhaustedMessage(error);
	} else if (diagnostic.status === 429) {
		message = getRateLimitMessage(error);
	}
	return { type: determineErrorType(error, message), message, diagnostic };
}

import { extractErrorStatus } from "./error-policy.js";
import { isHevyHttpError } from "@hevy-mcp/hevy-client";

export type HevyReadOperation = "get" | "list";
export type Expected404Outcome = "not_found" | "end_of_list";

const READ_RESOURCE_ENDPOINTS = new Set([
	"/v1/body_measurements/:date",
	"/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders/:folderId",
	"/v1/routines/:routineId",
	"/v1/workouts/:workoutId",
]);

const LIST_ENDPOINTS = new Set([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/workouts",
	"/v1/workouts/events",
]);

const MUTATION_ENDPOINTS = new Set([
	"/v1/body_measurements",
	"/v1/body_measurements/:date",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/routines/:routineId",
	"/v1/workouts",
	"/v1/workouts/:workoutId",
]);

/** True only for a sanitized Hevy GET of a known single resource. */
export function isExpectedReadNotFound(error: unknown): boolean {
	return (
		isHevyHttpError(error) &&
		extractErrorStatus(error) === 404 &&
		error.method.toUpperCase() === "GET" &&
		READ_RESOURCE_ENDPOINTS.has(error.endpoint)
	);
}

/** True only for an undocumented empty page after the first page. */
export function isExpectedListPageNotFound(
	error: unknown,
	page: number,
): boolean {
	return (
		page > 1 &&
		isHevyHttpError(error) &&
		extractErrorStatus(error) === 404 &&
		error.method.toUpperCase() === "GET" &&
		LIST_ENDPOINTS.has(error.endpoint)
	);
}

/** Mutation/caller 404s remain MCP errors but do not create Sentry issues. */
export function isExpectedMutationNotFound(error: unknown): boolean {
	return (
		isHevyHttpError(error) &&
		extractErrorStatus(error) === 404 &&
		error.method.toUpperCase() !== "GET" &&
		MUTATION_ENDPOINTS.has(error.endpoint)
	);
}

import type { CacheObservationMetadata, CacheObserver } from "@hevy-mcp/core";
import { SAFE_OBSERVATION_CODES } from "@hevy-mcp/hevy-client";
import type {
	HevyClientOptions,
	HevyRequestObservation,
	HevyRequestStart,
} from "@hevy-mcp/hevy-client";
import { context, SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import { debugLog } from "./debug.js";
import { apiCalls, apiDuration } from "./metrics.js";
import { bucketCount } from "./result-telemetry.js";
import {
	getCurrentMcpSessionId,
	getCurrentMcpTransport,
} from "./mcp-session-observability.js";
import { projectExecutionAttributes } from "./execution-telemetry.js";
import { tracer } from "./telemetry.js";

const SAFE_STATIC_ENDPOINTS = new Set([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/user/info",
	"/v1/workouts",
	"/v1/workouts/count",
	"/v1/workouts/events",
]);
const SAFE_DYNAMIC_ENDPOINTS = [
	["/v1/body_measurements/", "/v1/body_measurements/:date"],
	["/v1/exercise_history/", "/v1/exercise_history/:exerciseTemplateId"],
	["/v1/exercise_templates/", "/v1/exercise_templates/:exerciseTemplateId"],
	["/v1/routine_folders/", "/v1/routine_folders/:folderId"],
	["/v1/routines/", "/v1/routines/:routineId"],
	["/v1/workouts/", "/v1/workouts/:workoutId"],
] as const;

function normalizeHevyMetricEndpoint(endpoint: string): string {
	const path = endpoint.split("?")[0] ?? "";
	if (SAFE_STATIC_ENDPOINTS.has(path)) return path;
	return (
		SAFE_DYNAMIC_ENDPOINTS.find(([prefix]) => path.startsWith(prefix))?.[1] ??
		"unknown"
	);
}

function safeErrorAttributes(observation: HevyRequestObservation): {
	error_category?: string;
	error_code?: string;
} {
	if (!observation.error) return {};
	const code = observation.error.code;
	return {
		error_category: observation.error.category ?? "HevyHttpError",
		...(code && SAFE_OBSERVATION_CODES.has(code) ? { error_code: code } : {}),
	};
}

function startApiSpan(start: HevyRequestStart) {
	const sessionId = getCurrentMcpSessionId();
	return tracer.startSpan(`hevy.api.${start.method}`, {
		attributes: {
			"mcp.span.category": "api",
			"http.request.method": start.method,
			"hevy.api.endpoint": start.endpoint,
			"hevy.api.retry_count_bucket": bucketCount(start.retryCount),
			"mcp.transport": getCurrentMcpTransport(),
			...(sessionId ? { "mcp.session.id": sessionId } : {}),
		},
	});
}
function finishApiSpan(span: Span, observation: HevyRequestObservation): void {
	const errorAttributes = safeErrorAttributes(observation);
	if (observation.status > 0) {
		span.setAttribute("http.response.status_code", observation.status);
	}
	for (const [key, value] of Object.entries(
		projectExecutionAttributes(observation),
	)) {
		span.setAttribute(key, value);
	}
	if (observation.expectedReason) {
		span.setAttribute("hevy.api.expected_reason", observation.expectedReason);
	}
	for (const [key, value] of Object.entries(errorAttributes)) {
		span.setAttribute(key, value);
	}
	span.setStatus({
		code:
			observation.outcome === "success" || observation.outcome === "expected"
				? SpanStatusCode.OK
				: SpanStatusCode.ERROR,
	});
	if (observation.outcome !== "success" && observation.outcome !== "expected") {
		span.addEvent("hevy.api.failure", {
			"error.category": errorAttributes.error_category ?? "HevyHttpError",
			...(errorAttributes.error_code
				? { "error.code": errorAttributes.error_code }
				: {}),
		});
	}
	span.end();
}

/** Node-only adapter; the Worker graph never imports telemetry or metrics. */
export function createNodeHevyClientOptions(): HevyClientOptions {
	const rawTimeout = process.env.HEVY_MCP_API_TIMEOUT;
	const parsedTimeout = rawTimeout ? Number(rawTimeout) : Number.NaN;
	const timeoutMs =
		Number.isFinite(parsedTimeout) && parsedTimeout > 0
			? Math.floor(parsedTimeout)
			: undefined;
	return {
		...(timeoutMs ? { timeoutMs } : {}),
		onRequestStart(start) {
			const span = startApiSpan(start);
			return {
				run<T>(operation: () => Promise<T>) {
					return context.with(trace.setSpan(context.active(), span), operation);
				},
				finish(observation) {
					finishApiSpan(span, observation);
				},
			};
		},
		onRequestComplete(observation) {
			const retryCountBucket = bucketCount(observation.retryCount);
			const errorAttributes = safeErrorAttributes(observation);
			const metricEndpoint = normalizeHevyMetricEndpoint(observation.endpoint);
			const metricExecutionAttributes = projectExecutionAttributes(
				observation,
				"metric",
			);
			apiCalls.add(1, {
				method: observation.method,
				endpoint: metricEndpoint,
				status_code: observation.status,
				retry_count_bucket: retryCountBucket,
				...metricExecutionAttributes,
				transport: getCurrentMcpTransport(),
				...(observation.expectedReason
					? { expected_reason: observation.expectedReason }
					: {}),
				...errorAttributes,
			});
			apiDuration.record(observation.durationMs, {
				method: observation.method,
				endpoint: metricEndpoint,
				retry_count_bucket: retryCountBucket,
				...metricExecutionAttributes,
				transport: getCurrentMcpTransport(),
				...(observation.expectedReason
					? { expected_reason: observation.expectedReason }
					: {}),
				...errorAttributes,
			});
			debugLog("api_response", {
				method: observation.method,
				endpoint: observation.endpoint,
				durationMs: observation.durationMs,
				status: observation.status || null,
				retryCountBucket,
				outcome: observation.outcome,
				...errorAttributes,
			});
		},
		onRetryWait(observation) {
			const sessionId = getCurrentMcpSessionId();
			const span = tracer.startSpan("hevy.api.retry_wait", {
				attributes: {
					"mcp.span.category": "api",
					"http.request.method": observation.method,
					"hevy.api.retry_count_bucket": bucketCount(observation.retryCount),
					"hevy.api.retry_wait_ms": Math.max(
						0,
						Math.min(5_000, observation.delayMs),
					),
					...(sessionId ? { "mcp.session.id": sessionId } : {}),
				},
			});
			return { finish: () => span.end() };
		},
	};
}
export function createNodeCacheObserver(): CacheObserver {
	return {
		start(observation) {
			const sessionId = getCurrentMcpSessionId();
			const span = tracer.startSpan(`hevy.cache.${observation.state}`, {
				attributes: {
					"mcp.span.category": "cache",
					"hevy.cache.state": observation.state,
					"mcp.transport": getCurrentMcpTransport(),
					...(sessionId ? { "mcp.session.id": sessionId } : {}),
				},
			});
			return {
				finish(metadata?: CacheObservationMetadata) {
					if (metadata?.refreshReason) {
						span.setAttribute(
							"hevy.cache.refresh_reason",
							metadata.refreshReason,
						);
					}
					if (metadata?.pageCountBucket) {
						span.setAttribute(
							"hevy.cache.page_count_bucket",
							metadata.pageCountBucket,
						);
					}
					if (metadata?.itemCountBucket) {
						span.setAttribute(
							"hevy.cache.item_count_bucket",
							metadata.itemCountBucket,
						);
					}
					span.end();
				},
			};
		},
	};
}

import type {
	HevyClient,
	HevyExecutionOptions,
	HevyHttpError,
	HevyOperationSafety,
} from "@hevy-mcp/hevy-client";
import type { GetV1Workouts200, Workout } from "@hevy-mcp/hevy-client/types";
import { isHevyHttpError } from "@hevy-mcp/hevy-client";

export interface WorkoutsListInput {
	readonly page: number;
	readonly pageSize: number;
}

export interface WorkoutsListOutput {
	readonly items: Workout[];
	readonly page: number;
	readonly pageCount?: number;
	readonly expected404Outcome?: "end_of_list";
}

export type WorkoutsListAdapter = Pick<HevyClient, "getWorkouts">;

export interface WorkoutsListDescriptor {
	readonly id: "workouts.list";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const workoutsListDescriptor: WorkoutsListDescriptor = {
	id: "workouts.list",
	safety: "read",
};

export interface WorkoutsListOperation {
	readonly descriptor: WorkoutsListDescriptor;
	execute(
		input: WorkoutsListInput,
		options?: HevyExecutionOptions,
	): Promise<WorkoutsListOutput>;
}

function isExpectedEndOfList(error: unknown, page: number): boolean {
	return (
		page > 1 &&
		isHevyHttpError(error) &&
		error.status === 404 &&
		error.method.toUpperCase() === "GET" &&
		error.endpoint === "/v1/workouts"
	);
}

function normalizeWorkoutsPage(
	response: GetV1Workouts200,
	input: WorkoutsListInput,
): WorkoutsListOutput {
	if (response.page !== undefined && response.page !== input.page) {
		throw new Error(
			`Workouts page mismatch: requested page ${input.page} but received page ${response.page}`,
		);
	}
	return {
		items: response.workouts ?? [],
		page: response.page ?? input.page,
		pageCount: response.page_count,
	};
}

export function createWorkoutsListOperation(
	adapter: WorkoutsListAdapter,
): WorkoutsListOperation {
	return {
		descriptor: workoutsListDescriptor,
		async execute(input, options) {
			try {
				const params = { page: input.page, pageSize: input.pageSize };
				const response =
					options === undefined
						? await adapter.getWorkouts(params)
						: await adapter.getWorkouts(params, options);
				return normalizeWorkoutsPage(response, input);
			} catch (error) {
				if (isExpectedEndOfList(error, input.page)) {
					return {
						items: [],
						page: input.page,
						pageCount: undefined,
						expected404Outcome: "end_of_list",
					};
				}
				throw error;
			}
		},
	};
}

export function isWorkoutsListEndOfList(
	error: unknown,
	page: number,
): error is HevyHttpError {
	return isExpectedEndOfList(error, page);
}

import { describe, expect, it, vi } from "vitest";
import { createHevyClient } from "./hevy-client.js";
import {
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	HevyHttpError,
} from "./hevy-http-error.js";
import { createExecutionSignal, isAbortLike } from "./execution.js";
function response(data: unknown, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "content-type": "application/json" },
	});
}

function hangingResponse(): Response {
	return new Response(
		new ReadableStream({
			start(controller) {
				controller.enqueue(new TextEncoder().encode('{"routine":'));
			},
		}),
		{ status: 200, headers: { "content-type": "application/json" } },
	);
}

describe("@hevy-mcp/hevy-client", () => {
	it("uses object-form options and safely encodes requests", async () => {
		const fetchMock = vi.fn(
			async (input: RequestInfo | URL, init?: RequestInit) => {
				const requestUrl =
					input instanceof Request
						? input.url
						: input instanceof URL
							? input.href
							: input;
				const url = new URL(requestUrl);
				expect(url.pathname).toBe("/v1/workouts");
				expect(url.searchParams.get("page")).toBe("2");
				expect(new Headers(init?.headers).get("api-key")).toBe("secret-key");
				return response({ page: 2 });
			},
		);

		const client = createHevyClient({
			apiKey: "secret-key",
			fetch: fetchMock,
			maxGetRetries: 0,
		});

		await expect(client.getWorkouts({ page: 2, pageSize: 5 })).resolves.toEqual(
			{
				page: 2,
			},
		);
		expect(fetchMock).toHaveBeenCalledOnce();
	});

	it("does not abort an execution signal twice", () => {
		const execution = createExecutionSignal({});
		execution.abort(new DOMException("done", "AbortError"));
		execution.abort(new DOMException("ignored", "AbortError"));
		execution.cleanup();
		expect(execution.signal.reason).toMatchObject({ message: "done" });
	});

	it.each(["AbortError", "TimeoutError"])(
		"recognizes plain Error %s values as abort-like",
		(name) => {
			const error = new Error(name);
			error.name = name;
			expect(isAbortLike(error)).toBe(true);
		},
	);

	it("does not classify unrelated errors as abort-like", () => {
		expect(isAbortLike(new Error("network failure"))).toBe(false);
		expect(isAbortLike({ name: "AbortError" })).toBe(false);
	});

	it("synchronizes HevyHttpError execution aliases", () => {
		const error = new HevyHttpError("request failed", {
			method: "PUT",
			endpoint: "/v1/workouts/:workoutId",
		});
		error.setExecutionMetadata({
			phase: "dispatch",
			operationSafety: "idempotent-write",
			commitState: "unknown",
			safeToRetry: true,
			outcome: "retryable_failure",
		});

		expect(error).toMatchObject({
			phase: "dispatch",
			phase_name: "dispatch",
			operationSafety: "idempotent-write",
			operation_safety: "idempotent-write",
			commitState: "unknown",
			commit_state: "unknown",
			safeToRetry: true,
			safe_to_retry: true,
			outcome: "retryable_failure",
		});
	});

	it("emits bounded events without raw response or exception data", async () => {
		const onLog = vi.fn(() => {
			throw new Error("observer-secret");
		});
		const onRequestComplete = vi.fn(() => {
			throw new Error("completion-secret");
		});
		const fetchMock = vi
			.fn()
			.mockResolvedValue(response({ secret: "body" }, 401));
		const client = createHevyClient({
			apiKey: "api-key-secret",
			fetch: fetchMock,
			maxGetRetries: 0,
			onLog,
			onRequestComplete,
		});

		await expect(client.getUserInfo()).rejects.toBeInstanceOf(HevyHttpError);
		const eventText = JSON.stringify(onRequestComplete.mock.calls);
		expect(eventText).not.toContain("api-key-secret");
		expect(eventText).not.toContain("body");
		expect(eventText).not.toContain("observer-secret");
		expect(onLog).toHaveBeenCalled();
	});
	it("times out while consuming a response body", async () => {
		const fetchMock = vi.fn().mockResolvedValue(hangingResponse());
		const client = createHevyClient({
			apiKey: "secret-key",
			fetch: fetchMock,
			timeoutMs: 20,
			maxGetRetries: 0,
		});

		await expect(client.getRoutineById("routine-1")).rejects.toMatchObject({
			code: HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
			phase: "response-content",
			outcome: "deadline_exceeded",
		});
	});

	it("times out when fetch never settles", async () => {
		const fetchMock = vi.fn(() => new Promise<Response>(() => {}));
		const client = createHevyClient({
			apiKey: "secret-key",
			fetch: fetchMock,
			timeoutMs: 20,
			maxGetRetries: 0,
		});

		await expect(client.getRoutineById("routine-1")).rejects.toMatchObject({
			code: HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
			phase: "dispatch",
			outcome: "deadline_exceeded",
		});
	});
