			safeToRetry: true,
			outcome: "retryable_failure",
		});

		expect(error).toMatchObject({
			phase: "dispatch",
			phase_name: "dispatch",
			operationSafety: "idempotent-write",
			operation_safety: "idempotent-write",
			commitState: "unknown",

