class HttpRequestError extends Error {
	readonly statusCode: number;

	constructor(statusCode: number, message: string) {
		super(message);
		this.name = "HttpRequestError";
		this.statusCode = statusCode;
	}
}

function normalizeHost(host: string): string {
	return host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host;
}

function isLoopbackHost(host: string): boolean {
	const normalized = normalizeHost(host).toLowerCase();
	return (
		normalized === "localhost" ||
		normalized === "127.0.0.1" ||
		normalized === "::1"
	);
}

function hostNamesFor(options: NodeCliOptions): Set<string> {
	const configured = normalizeHost(options.host).toLowerCase();
	const names = new Set([configured]);
	if (isLoopbackHost(options.host)) {
		names.add("localhost");
		names.add("127.0.0.1");
		names.add("::1");
	}
	return names;
}

function expectedPort(options: NodeCliOptions, server: Server): number {
	if (options.port !== 0) return options.port;
	const address = server.address();
	return address && typeof address !== "string" ? address.port : 0;
}

function validateHostHeader(
	request: IncomingMessage,
	allowedHosts: Set<string>,
	port: number,
	allowAnyHostname = false,
): boolean {
	const header = request.headers.host;
	if (!header || Array.isArray(header)) return false;
	try {
		const parsed = new URL(`http://${header}`);
		if (
			parsed.username ||
			parsed.password ||
			parsed.pathname !== "/" ||
			parsed.search ||
			parsed.hash ||
			(!allowAnyHostname && (parsed.port ? Number(parsed.port) : 80) !== port)
		) {
			return false;
		}
		return (
			allowAnyHostname ||
			allowedHosts.has(normalizeHost(parsed.hostname).toLowerCase())
		);
	} catch {
		return false;
	}
}

function safeDiagnostic(error: unknown): string {
	return JSON.stringify(createSafeErrorDiagnostic(error));
}

function writeJson(res: ServerResponse, status: number, message: string): void {
	if (res.headersSent) return;
	res.statusCode = status;
	res.setHeader("Content-Type", "application/json");
	res.end(JSON.stringify({ error: message }));
}

function writeExecutionJson(
	res: ServerResponse,
	status: number,
	message: string,
	error: unknown,
): void {
	if (res.headersSent) return;
	const diagnostic = createSafeErrorDiagnostic(error);
	const execution = createExecutionProjection(diagnostic);
	res.statusCode = status;
	res.setHeader("Content-Type", "application/json");
	res.end(
		JSON.stringify({
			error: { message, ...execution },
		}),
	);
}

function readBody(request: IncomingMessage): Promise<unknown> {
	return new Promise((resolve, reject) => {
		let size = 0;
		let rejected = false;
		const chunks: Buffer[] = [];
		const onData = (chunk: Buffer | string) => {
			const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
			size += buffer.byteLength;
			if (size > MAX_BODY_BYTES) {
				if (!rejected) {
					rejected = true;
					request.removeListener("data", onData);
					request.resume();
					reject(new HttpRequestError(413, "Request body is too large."));
				}
				return;
			}
			if (!rejected) chunks.push(buffer);
		};
		request.on("data", onData);
		request.once("error", (error) => {
			if (!rejected) reject(error);
		});
		request.once("end", () => {
			if (rejected) return;
			try {
				const raw = Buffer.concat(chunks).toString("utf8");
				resolve(raw.length === 0 ? undefined : JSON.parse(raw));
			} catch {
				reject(new HttpRequestError(400, "Request body must be valid JSON."));
			}
		});
	});
}

function isInitializeRequest(body: unknown): boolean {
	return Boolean(
		body &&
		typeof body === "object" &&
		!Array.isArray(body) &&
		"method" in body &&
		body.method === "initialize",
	);
}

function closeServer(server: Server): Promise<void> {
	return new Promise((resolve, reject) => {
		if (!server.listening) {
			resolve();
			return;
		}
		server.close((error) => (error ? reject(error) : resolve()));
		server.closeIdleConnections();
		server.closeAllConnections();
	});
}

function isBearerAuthorized(
	request: IncomingMessage,
	token: string | undefined,
): boolean {
	if (!token) return false;
	const header = request.headers.authorization;
	if (typeof header !== "string") return false;
	const expected = Buffer.from(`Bearer ${token}`);
	const actual = Buffer.from(header);
	return (
		expected.byteLength === actual.byteLength &&
		timingSafeEqual(expected, actual)
	);
}

function aggregateErrors(errors: unknown[], message: string): unknown {
	if (errors.length === 1) return errors[0];
	return new AggregateError(errors, message);
}

export function isHttpHostAllowed(host: string): boolean {
	return isLoopbackHost(host);
}

export async function startStreamableHttpServer(
	options: NodeCliOptions,
	apiKey: string,
	createMcpServer: McpServerFactory,
): Promise<HttpServerHandle> {
	const wildcard =
		options.host === "0.0.0.0" ||
		options.host === "::" ||
		options.host === "[::]";
	const loopback = isLoopbackHost(options.host);
	const bearerToken = process.env[HTTP_BEARER_TOKEN];
	if (!loopback && !bearerToken) {
		throw new Error(
			`Non-loopback HTTP mode requires ${HTTP_BEARER_TOKEN} to protect the shared Hevy account.`,
		);
	}

	const sessions = new Map<string, HttpSession>();
	const cleanupErrors: unknown[] = [];
	const server = createServer((request, response) => {
		void handleRequest(request, response).catch((error: unknown) => {
			if (response.headersSent) {
				if (!response.writableEnded) response.destroy();
				return;
			}
			if (error instanceof HttpRequestError) {
				writeJson(response, error.statusCode, error.message);
				return;
			}
			console.error(`HTTP request failed: ${safeDiagnostic(error)}`);
			writeExecutionJson(response, 500, "Internal server error.", error);
		});
	});

	async function closeSession(
		session: HttpSession,
		failureCategory?: "connect_failure" | "startup_failure" | "unknown",
	): Promise<void> {
		if (session.closed) return;
		session.closed = true;
		for (const [id, current] of sessions) {
			if (current === session) sessions.delete(id);
		}
		for (const response of session.responses) {
			if (!response.writableEnded) response.destroy();
		}
		// The SDK transport closes response streams, but its stateful close path
		// does not abort the request signal already handed to MCP handlers. Abort
		// the session-owned lifecycle signal first so active Hevy calls stop too.
		session.lifecycleController.abort(
			new DOMException("MCP session closed", "AbortError"),
		);

		const results = await Promise.allSettled([
			Promise.resolve().then(() => session.transport.close()),
			Promise.resolve().then(() => session.server.close()),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		const succeeded = errors.length === 0;
		recordMcpSessionTermination(
			failureCategory && succeeded
				? failureCategory
				: resolveSessionTerminationCategory(succeeded, session.context),
			session.context,
		);
		if (errors.length > 0) {
			throw aggregateErrors(errors, "MCP session cleanup failed.");
		}
	}

	async function closeUnregistered(
		transport: HttpTransport,
		mcpServer: OwnedMcpServer | undefined,
	): Promise<void> {
		const results = await Promise.allSettled([
			Promise.resolve().then(() => transport.close()),
			...(mcpServer ? [Promise.resolve().then(() => mcpServer.close())] : []),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		if (errors.length > 0) throw aggregateErrors(errors, "MCP cleanup failed.");
		return;
	}

	function trackSessionResponse(
		session: HttpSession,
		response: ServerResponse,
	): void {
		session.responses.add(response);
		response.once("close", () => {
			session.responses.delete(response);
			// A destroyed response means the client disconnected before the
			// exchange completed. The SDK does not expose a request-scoped signal
			// for this transport, so evict and close the whole session rather than
			// leaving an aborted session reusable or poisoning future requests.
			if (!response.writableEnded && !session.closed) {
				void closeSession(session).catch((error: unknown) => {
					cleanupErrors.push(error);
				});
			}
		});
	}

	async function handleRequest(
		request: IncomingMessage,
		response: ServerResponse,
	): Promise<void> {
		if (request.url?.split("?", 1)[0] !== MCP_PATH) {
			writeJson(response, 404, "Not found");
			return;
		}
		if (
			!validateHostHeader(
				request,
				hostNamesFor(options),
				expectedPort(options, server),
				wildcard,
			)
		) {
			writeJson(response, 403, "Invalid Host header");
			return;
		}
		if (!loopback && !isBearerAuthorized(request, bearerToken)) {
			writeJson(response, 401, "Authorization required");
			return;
		}

		const body =
			request.method === "POST" ? await readBody(request) : undefined;
		const initializing = request.method === "POST" && isInitializeRequest(body);
		const sessionHeader = request.headers["mcp-session-id"];
		const sessionId =
			typeof sessionHeader === "string" ? sessionHeader : undefined;

		if (initializing) {
			if (sessionId) {
				writeJson(
					response,
					400,
					"Initialization must not include Mcp-Session-Id.",
				);
				return;
			}
			const context = createMcpSessionContext(body, "http");
			recordMcpSessionStart(body, "http", context);
			let session: HttpSession | undefined;
			let mcpServer: OwnedMcpServer | undefined;
			let connected = false;
			const lifecycleController = new AbortController();
			const transport = new NodeStreamableHTTPServerTransport({
				sessionIdGenerator: randomUUID,
				onsessioninitialized: (id) => {
					if (session) sessions.set(id, session);
				},
			});
			transport.onclose = () => {
				if (session) {
					void closeSession(session).catch((error: unknown) => {
						cleanupErrors.push(error);
					});
				}
			};
			try {
				mcpServer = await createMcpServer({
					apiKey,
					lifecycleSignal: lifecycleController.signal,
				});
				session = {
					transport,
					server: mcpServer,
					context,
					lifecycleController,
					responses: new Set(),
					closed: false,
				};
				await mcpServer.connect(transport);
				connected = true;
				trackSessionResponse(session, response);
				await runWithMcpSessionContext(context, () =>
					transport.handleRequest(request, response, body),
				);
			} catch (error) {
				lifecycleController.abort(
					new DOMException("MCP session startup failed", "AbortError"),
				);
				console.error(`HTTP session request failed: ${safeDiagnostic(error)}`);
				let cleanupError: unknown;
				try {
					if (session) {
						await closeSession(
							session,
							connected ? "unknown" : "connect_failure",
						);
					} else {
						await closeUnregistered(transport, mcpServer);
						recordMcpSessionTermination("startup_failure", context);
					}
				} catch (cleanupFailure) {
					cleanupError = cleanupFailure;
					if (!session) recordMcpSessionTermination("unknown", context);
				}
				if (cleanupError) {
					console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
				}
				if (!response.writableEnded)
					writeExecutionJson(response, 500, "Internal server error.", error);
			}
			return;
		}

		if (!sessionId) {
			writeJson(response, 400, "Mcp-Session-Id header is required.");
			return;
		}
		const session = sessions.get(sessionId);
		if (!session) {
			writeJson(response, 404, "Unknown Mcp-Session-Id.");
			return;
		}
		if (request.method !== "DELETE") {
			trackSessionResponse(session, response);
		}
		await runWithMcpSessionContext(session.context, () =>
			session.transport.handleRequest(request, response, body),
		);
	}

	await new Promise<void>((resolve, reject) => {
		server.once("error", reject);
		server.listen(options.port, options.host, () => {
			server.removeListener("error", reject);
			resolve();
		});
	});

	let closePromise: Promise<void> | undefined;
	return {
		server,
		close: () => {
			if (closePromise) return closePromise;
			closePromise = (async () => {
				const sessionsToClose = [...sessions.values()];
				const results = await Promise.allSettled([
					...sessionsToClose.map((session) => closeSession(session)),
					closeServer(server),
				]);
				sessions.clear();
				const errors = [
					...cleanupErrors,
					...results.flatMap((result) =>
						result.status === "rejected" ? [result.reason] : [],
					),
				];
				if (errors.length > 0) {
					throw aggregateErrors(errors, "HTTP server cleanup failed.");
				}
			})();
			return closePromise;
		},
	};
}

import { isIP } from "node:net";

export type NodeTransport = "stdio" | "http";

export interface NodeCliOptions {
	transport: NodeTransport;
	host: string;
	port: number;
}

const DEFAULT_HOST = "127.0.0.1";
const DEFAULT_PORT = 3000;

function valueAfter(args: string[], index: number, option: string): string {
	const value = args[index + 1];
	if (!value || value.startsWith("-")) {
		throw new Error(`${option} requires a value.`);
	}
	return value;
}

function parseHost(value: string): string {
	const host = value.trim();
	const unbracketed =
		host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host;
	const isBracketed = host.startsWith("[") || host.endsWith("]");
	const validHostname =
		/^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)*[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/u;
	if (
		host.length === 0 ||
		(isBracketed && !(host.startsWith("[") && host.endsWith("]"))) ||
		(isBracketed && isIP(unbracketed) !== 6) ||
		(!isBracketed && host.includes(":") && isIP(host) !== 6) ||
		(!isBracketed &&
			!host.includes(":") &&
			isIP(host) === 0 &&
			!validHostname.test(host)) ||
		/\s/u.test(host) ||
		host.includes("/") ||
		host.includes("@") ||
		host.includes("://")
	) {
		throw new Error(
			`Invalid host: ${value}. Provide a hostname or IP address.`,
		);
	}
	return unbracketed;
}

function parsePort(value: string): number {
	if (!/^[0-9]+$/u.test(value)) {
		throw new Error(`Invalid port: ${value}. Use an integer from 1 to 65535.`);
	}
	const port = Number(value);
	if (!Number.isSafeInteger(port) || port < 1 || port > 65535) {
		throw new Error(`Invalid port: ${value}. Use an integer from 1 to 65535.`);
	}
	return port;
}

export function parseNodeCliOptions(args: string[]): NodeCliOptions {
	let transport: NodeTransport = "stdio";
	let host = DEFAULT_HOST;
	let port = DEFAULT_PORT;
	let transportExplicit = false;
	let hostExplicit = false;
	let portExplicit = false;

	for (let index = 0; index < args.length; index += 1) {
		const arg = args[index];
		if (!arg || ["--help", "-h", "--version", "-v"].includes(arg)) {
			continue;
		}
		switch (arg) {
			case "--transport": {
				const value = valueAfter(args, index, arg);
				index += 1;
				if (value !== "stdio" && value !== "http") {
					throw new Error(
						`Invalid transport: ${value}. Use either stdio or http.`,
					);
				}
				transport = value;
				transportExplicit = true;
				break;
			}
			case "--host":
				host = parseHost(valueAfter(args, index, arg));
				hostExplicit = true;
				index += 1;
				break;
			case "--port":
				port = parsePort(valueAfter(args, index, arg));
				portExplicit = true;
				index += 1;
				break;
			default:
				throw new Error(`Unknown option: ${arg}`);
		}
	}

	if (transport === "stdio" && (hostExplicit || portExplicit)) {
		throw new Error(
			"--host and --port can only be used with --transport http.",
		);
	}
	if (transport === "stdio" && transportExplicit) {
		return { transport, host: DEFAULT_HOST, port: DEFAULT_PORT };
	}
	return { transport, host, port };
}

// Telemetry must be initialized before any other imports so that
// OpenTelemetry and Sentry are ready before application code runs.
import { tracer, serviceName, serviceVersion } from "./utils/telemetry.js";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { SpanStatusCode } from "@opentelemetry/api";
import { z } from "zod";
import { createHevyMcpServer, mergeAbortSignals } from "@hevy-mcp/core";
import { createHevyClient, isHevyHttpError } from "@hevy-mcp/hevy-client";
import { assertApiKey, parseConfig } from "./utils/config.js";
import { parseNodeCliOptions, type NodeTransport } from "./utils/arguments.js";
import { startStreamableHttpServer } from "./utils/streamable-http.js";
import {
	createNodeCacheObserver,
	createNodeHevyClientOptions,
} from "./utils/hevy-client-observability.js";
import { createNodeToolObserver } from "./utils/tool-observer.js";
import { createInstrumentedStdioTransport } from "./utils/stdio-observability.js";
import {
	recordMcpSessionTermination,
	resolveSessionTerminationCategory,
} from "./utils/mcp-session-observability.js";
import { installSdkErrorTracking } from "./utils/sdk-observability.js";
import {
	INVALID_API_KEY_MESSAGE,
	recordLifecycleFailure,
	runNodeLifecycle,
} from "./utils/node-lifecycle.js";

const name = serviceName;
const version = serviceVersion;

const HELP_TEXT = [
	"Usage:",
	"  hevy-mcp [options]",
	"",
	"Options:",
	"  -h, --help                 Show this help message and exit",
	"  -v, --version              Show version and exit",
	"  --transport stdio|http     Select the transport (default: stdio)",
	"  --host <host>              HTTP bind host (default: 127.0.0.1)",
	"  --port <port>              HTTP bind port (default: 3000)",
	"",
	"Environment:",
	"  HEVY_API_KEY=<api-key>     Hevy API key from Hevy app settings",
	"  HEVY_MCP_DEBUG=1           Enable verbose diagnostics on stderr",
	"  HEVY_MCP_HTTP_BEARER_TOKEN Protect non-loopback HTTP deployments",
	"  HEVY_MCP_TELEMETRY=0     Disable all project telemetry",
	"  HEVY_MCP_TELEMETRY_DIAGNOSTICS=0  Suppress exception details",
	"",
	"Examples:",
	"  HEVY_API_KEY=your-key npx hevy-mcp",
	"  HEVY_API_KEY=your-key npx hevy-mcp --transport http --port 3000",
].join("\n");

function getCliAction(args: string[]): "start" | "version" | "help" {
	for (const arg of args) {
		if (arg === "--version" || arg === "-v") {
			return "version";
		}

		if (arg === "--help" || arg === "-h") {
			return "help";
		}
	}

	return "start";
}

const HEVY_API_BASEURL = "https://api.hevyapp.com";
const STARTUP_PROBE_TIMEOUT_MS = 5_000;

const API_KEY_VALIDATION_WARNING =
	"Warning: HEVY_API_KEY could not be validated during startup. Startup will continue; check your network connection and Hevy API availability.";
const SAFE_NETWORK_ERROR_CODES = new Set([
	"EAI_AGAIN",
	"ECONNABORTED",
	"ECONNREFUSED",
	"ECONNRESET",
	"ENETUNREACH",
	"ENOTFOUND",
	"ERR_NETWORK",
	"ERR_SOCKET_TIMEOUT",
	"ETIMEDOUT",
	"HEVY_RETRY_EXHAUSTED",
]);

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});

function getHttpStatus(error: unknown): number | undefined {
	if (isHevyHttpError(error)) {
		return error.status;
	}
	if (!error || typeof error !== "object" || !("response" in error)) {
		return undefined;
	}

	const response = error.response;
	if (!response || typeof response !== "object" || !("status" in response)) {
		return undefined;
	}

	return typeof response.status === "number" &&
		Number.isInteger(response.status) &&
		response.status >= 100 &&
		response.status <= 599
		? response.status
		: undefined;
}

function getSafeValidationDiagnostic(error: unknown): string | undefined {
	const status = getHttpStatus(error);
	if (status !== undefined) {
		return `HTTP ${status}`;
	}

	if (!error || typeof error !== "object" || !("code" in error)) {
		return undefined;
	}

	const code = error.code;
	return typeof code === "string" && SAFE_NETWORK_ERROR_CODES.has(code)
		? code
		: undefined;
}
async function validateApiKey(apiKey: string, signal?: AbortSignal) {
	// Keep the startup probe separate from the normal MCP-aware client. The
	// server is not connected yet, so structured client logging is intentionally
	// omitted until the normal client is built below.
	const startupProbeClient = createHevyClient({
		apiKey,
		baseUrl: HEVY_API_BASEURL,
		maxGetRetries: 0,
		timeoutMs: STARTUP_PROBE_TIMEOUT_MS,
	});

	try {
		await startupProbeClient.getUserInfo({
			signal,
			deadline: Date.now() + STARTUP_PROBE_TIMEOUT_MS,
		});
	} catch (error) {
		if (signal?.aborted) throw error;
		const status = getHttpStatus(error);
		if (status === 401 || status === 403) {
			throw new Error(INVALID_API_KEY_MESSAGE);
		}

		const diagnostic = getSafeValidationDiagnostic(error);
		console.error(
			diagnostic
				? `${API_KEY_VALIDATION_WARNING} Diagnostic: ${diagnostic}.`
				: API_KEY_VALIDATION_WARNING,
		);
	}
}

function buildServer(
	apiKey: string,
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	return tracer.startActiveSpan(
		"mcp.server.build",
		{
			attributes: {
				"mcp.span.category": "startup",
				"mcp.server.name": name,
				"mcp.server.version": version,
				"mcp.transport": transport,
			},
		},
		(span) => {
			try {
				const server = createHevyMcpServer({
					createClient: ({ onLog }) =>
						createHevyClient({
							apiKey,
							...createNodeHevyClientOptions(),
							onLog,
						}),
					lifecycleSignal,
					onToolsRegistered: (count) =>
						span.setAttribute("mcp.tools.count", count),
					observer: createNodeToolObserver(),
					cacheObserver: createNodeCacheObserver(),
				});
				installSdkErrorTracking(server, transport);
				console.error("Hevy client initialized with API key");

				span.setStatus({ code: SpanStatusCode.OK });
				return server;
			} catch (e) {
				recordLifecycleFailure(span, e, "build", "startup_failure");
				span.setStatus({ code: SpanStatusCode.ERROR });
				throw e;
			} finally {
				span.end();
			}
		},
	);
}

export async function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
	await validateApiKey(validatedApiKey, lifecycleSignal);
	return buildServer(validatedApiKey, transport, lifecycleSignal);
}

export async function runStdioServer() {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);

	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	await runNodeLifecycle({
		transport: "stdio",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			const apiKey = cfg.apiKey;
			assertApiKey(apiKey);
			const server = await createNodeMcpServer({ apiKey }, "stdio", signal);
			console.error("Starting MCP server in stdio mode");
			const transport = createInstrumentedStdioTransport(
				new StdioServerTransport(),
			);
			context.markConnectAttempted();
			await tracer.startActiveSpan(
				"mcp.server.connect",
				{
					attributes: {
						"mcp.span.category": "session",
						"mcp.transport": "stdio",
					},
				},
				async (connectSpan) => {
					try {
						await server.connect(transport);
						context.markConnectSucceeded();
						connectSpan.setStatus({ code: SpanStatusCode.OK });
					} catch (error) {
						recordLifecycleFailure(
							connectSpan,
							error,
							"connect",
							"connect_failure",
						);
						connectSpan.setStatus({ code: SpanStatusCode.ERROR });
						throw error;
					} finally {
						connectSpan.end();
					}
				},
			);
			return {
				target: server,
				onShutdown: (succeeded) =>
					recordMcpSessionTermination(
						resolveSessionTerminationCategory(succeeded),
					),
			};
		},
		onFailure: (reason, outcome) => {
			if (outcome.transport === "stdio") {
				recordMcpSessionTermination(reason);
			}
		},
	});
}

export async function runServer(): Promise<void> {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);
	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	const options = parseNodeCliOptions(args);
	if (options.transport === "stdio") {
		await runStdioServer();
		return;
	}

	await runNodeLifecycle({
		transport: "http",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			assertApiKey(cfg.apiKey);
			await validateApiKey(cfg.apiKey, signal);
			const handle = await startStreamableHttpServer(
				options,
				cfg.apiKey,
				(params) =>
					Promise.resolve(
						buildServer(
							params.apiKey,
							"http",
							mergeAbortSignals(signal, params.lifecycleSignal),
						),
					),
			);
			context.markListening();
			console.error(
				`Starting MCP server in HTTP mode at ${options.host}:${options.port}/mcp`,
			);
			return { target: handle };
		},
		onFailure: (_reason, outcome) => {
			if (outcome.transport === "http") {
				recordMcpSessionTermination(
					outcome.listening ? "unknown" : "startup_failure",
				);
			}
		},
	});
}

import { request, type Server } from "node:http";
import { McpServer } from "@modelcontextprotocol/server";
import { afterEach, describe, expect, it, vi } from "vitest";
import { startStreamableHttpServer } from "./streamable-http.js";

const createMcpServer = async () => {
	const server = new McpServer({ name: "test-server", version: "1.0.0" });
	server.registerTool(
		"mock-tool",
		{ description: "A mocked tool" },
		async () => ({ content: [{ type: "text", text: "mock result" }] }),
	);
	return server;
};

const handles: Array<{ close(): Promise<void> }> = [];

afterEach(async () => {
	await Promise.all(handles.splice(0).map((handle) => handle.close()));
});

interface HttpResult {
	statusCode?: number;
	headers: Record<string, string | string[] | undefined>;
	body: string;
}

function openStream(
	port: number,
	headers: Record<string, string>,
): Promise<{ ended: Promise<void> }> {
	return new Promise((resolve, reject) => {
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method: "GET",
				headers: { Accept: "text/event-stream", ...headers },
			},
			(response) => {
				const ended = new Promise<void>((finish) => {
					response.once("end", finish);
					response.once("close", finish);
				});
				resolve({ ended });
			},
		);
		client.once("error", reject);
		client.end();
	});
}

function call(
	port: number,
	method: string,
	body?: unknown,
	extraHeaders: Record<string, string> = {},
): Promise<HttpResult> {
	return new Promise((resolve, reject) => {
		const payload = body === undefined ? undefined : JSON.stringify(body);
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method,
				headers: {
					Accept: "application/json, text/event-stream",
					...(payload ? { "Content-Type": "application/json" } : {}),
					...extraHeaders,
				},
			},
			(response) => {
				const chunks: Buffer[] = [];
				response.on("data", (chunk: Buffer) => chunks.push(chunk));
				response.once("end", () =>
					resolve({
						statusCode: response.statusCode,
						headers: response.headers,
						body: Buffer.concat(chunks).toString("utf8"),
					}),
				);
			},
		);
		client.once("error", reject);
		if (payload) client.write(payload);
		client.end();
	});
}

function serverPort(handle: { server: Server }): number {
	const address = handle.server.address();
	if (!address || typeof address === "string") throw new Error("No address");
	return address.port;
}

function jsonBody(result: HttpResult): Record<string, unknown> {
	const json = result.body.startsWith("event:")
		? result.body
				.split("\n")
				.filter((line) => line.startsWith("data:"))
				.map((line) => line.slice("data:".length).trim())
				.join("\n")
		: result.body;
	if (!json) throw new Error(`empty response: ${JSON.stringify(result)}`);
	return JSON.parse(json) as Record<string, unknown>;
}

async function startTestServer(host = "127.0.0.1") {
	const handle = await startStreamableHttpServer(
		{ transport: "http", host, port: 0 },
		"test-key",
		createMcpServer,
	);
	handles.push(handle);
	return { handle, port: serverPort(handle) };
}

async function startDisconnectTestServer() {
	let releaseTool!: () => void;
	let markStarted!: () => void;
	const toolStarted = new Promise<void>((resolve) => {
		markStarted = resolve;
	});
	const toolRelease = new Promise<void>((resolve) => {
		releaseTool = resolve;
	});
	const createHangingServer = async () => {
		const server = new McpServer({ name: "test-server", version: "1.0.0" });
		server.registerTool(
			"mock-tool",
			{ description: "A mocked tool" },
			async () => {
				markStarted();
				await toolRelease;
				return { content: [{ type: "text", text: "mock result" }] };
			},
		);
		return server;
	};
	const started = await startStreamableHttpServer(
		{ transport: "http", host: "127.0.0.1", port: 0 },
		"test-key",
		createHangingServer,
	);
	handles.push(started);
	return { ...started, port: serverPort(started), toolStarted, releaseTool };
}

async function initialize(port: number, headers: Record<string, string> = {}) {
	return call(
		port,
		"POST",
		{
			jsonrpc: "2.0",
			id: 1,
			method: "initialize",
			params: {
				protocolVersion: "2025-06-18",
				capabilities: {},
				clientInfo: { name: "protocol-test", version: "1.0.0" },
			},
		},
		headers,
	);
}

describe("Streamable HTTP server", () => {
	it("supports initialize, tools/list, and a mocked tools/call", async () => {
		const { port } = await startTestServer();
		const initialized = await initialize(port);
		expect(initialized.statusCode).toBe(200);
		const sessionId = initialized.headers["mcp-session-id"];
		expect(typeof sessionId).toBe("string");

		const headers = { "mcp-session-id": String(sessionId) };
		const listed = await call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 2,
				method: "tools/list",
				params: {},
			},
			headers,
		);
		expect(listed.statusCode).toBe(200);
		expect(JSON.stringify(jsonBody(listed))).toContain("mock-tool");

		const called = await call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 3,
				method: "tools/call",
				params: { name: "mock-tool", arguments: {} },
			},
			headers,
		);
		expect(called.statusCode).toBe(200);
		expect(JSON.stringify(jsonBody(called))).toContain("mock result");
	});

	it("keeps two clients isolated and routes unknown sessions safely", async () => {
		const { port } = await startTestServer();
		const first = await initialize(port);
		const second = await initialize(port);
		const firstSession = String(first.headers["mcp-session-id"]);
		const secondSession = String(second.headers["mcp-session-id"]);
		expect(firstSession).not.toBe(secondSession);

		const firstList = await call(
			port,
			"POST",
			{ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} },
			{ "mcp-session-id": firstSession },
		);
		const secondList = await call(
			port,
			"POST",
			{ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} },
			{ "mcp-session-id": secondSession },
		);
		expect(firstList.statusCode).toBe(200);
		expect(secondList.statusCode).toBe(200);

		expect((await call(port, "POST", { jsonrpc: "2.0" })).statusCode).toBe(400);
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0", id: 4, method: "tools/list" },
					{ "mcp-session-id": "missing-session" },
				)
			).statusCode,
		).toBe(404);
	});

	it("removes a session on DELETE", async () => {
		const { port } = await startTestServer();
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const deleted = await call(port, "DELETE", undefined, {
			"mcp-session-id": sessionId,
		});
		expect(deleted.statusCode).toBe(200);
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0", id: 2, method: "tools/list" },
					{ "mcp-session-id": sessionId },
				)
			).statusCode,
		).toBe(404);
	});

	it("evicts a session after a disconnected request", async () => {
		const { port, toolStarted, releaseTool } =
			await startDisconnectTestServer();
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const payload = JSON.stringify({
			jsonrpc: "2.0",
			id: 2,
			method: "tools/call",
			params: { name: "mock-tool", arguments: {} },
		});
		const disconnected = request({
			host: "127.0.0.1",
			port,
			path: "/mcp",
			method: "POST",
			headers: {
				Accept: "application/json, text/event-stream",
				"Content-Type": "application/json",
				"mcp-session-id": sessionId,
			},
		});
		disconnected.once("error", () => {});
		disconnected.end(payload);
		await toolStarted;
		disconnected.destroy();

		await vi.waitFor(async () => {
			const aftermath = await call(
				port,
				"POST",
				{ jsonrpc: "2.0", id: 3, method: "tools/list", params: {} },
				{ "mcp-session-id": sessionId },
			);
			expect(aftermath.statusCode).toBe(404);
		});
		releaseTool();
	});

	it("aborts active session execution when DELETE closes the transport", async () => {
		let sessionSignal: AbortSignal | undefined;
		let markStarted!: () => void;
		const toolStarted = new Promise<void>((resolve) => {
			markStarted = resolve;
		});
		const createAbortAwareServer = async ({
			lifecycleSignal,
		}: {
			apiKey: string;
			lifecycleSignal?: AbortSignal;
		}) => {
			sessionSignal = lifecycleSignal;
			const server = new McpServer({ name: "abort-aware", version: "1.0.0" });
			server.registerTool(
				"mock-tool",
				{ description: "A mocked tool" },
				async () => {
					markStarted();
					await new Promise<void>((resolve) =>
						lifecycleSignal?.addEventListener("abort", () => resolve(), {
							once: true,
						}),
					);
					return { content: [{ type: "text", text: "aborted" }] };
				},
			);
			return server;
		};
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"test-key",
			createAbortAwareServer,
		);
		handles.push(handle);
		const port = serverPort(handle);
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const pendingCall = call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 2,
				method: "tools/call",
				params: { name: "mock-tool", arguments: {} },
			},
			{ "mcp-session-id": sessionId },
		).catch(() => undefined);
		await toolStarted;
		await expect(
			call(port, "DELETE", undefined, { "mcp-session-id": sessionId }),
		).resolves.toMatchObject({ statusCode: 200 });
		expect(sessionSignal?.aborted).toBe(true);
		void pendingCall;
	});

	it("requires bearer authentication for wildcard binds", async () => {
		process.env.HEVY_MCP_HTTP_BEARER_TOKEN = "http-test-token";
		try {
			const { port } = await startTestServer("0.0.0.0");
			expect((await initialize(port)).statusCode).toBe(401);
			const authorized = await initialize(port, {
				authorization: "Bearer http-test-token",
			});
			expect(authorized.statusCode).toBe(200);
		} finally {
			delete process.env.HEVY_MCP_HTTP_BEARER_TOKEN;
		}
	});

	it("returns safe 400/413 responses for malformed and oversized bodies", async () => {
		const { port } = await startTestServer();
		// Send malformed JSON directly because the helper serializes valid bodies.
		const invalid = await new Promise<HttpResult>((resolve, reject) => {
			const client = request(
				{ host: "127.0.0.1", port, path: "/mcp", method: "POST" },
				(response) => {
					const chunks: Buffer[] = [];
					response.on("data", (chunk: Buffer) => chunks.push(chunk));
					response.once("end", () =>
						resolve({
							statusCode: response.statusCode,
							headers: response.headers,
							body: Buffer.concat(chunks).toString("utf8"),
						}),
					);
				},
			);
			client.once("error", reject);
			client.end("not-json");
		});
		expect(invalid.statusCode).toBe(400);
		expect(invalid.body).not.toContain("not-json");

		const oversized = await call(port, "POST", "x".repeat(1_048_577));
		expect(oversized.statusCode).toBe(413);
	});

	it("returns structured errors when an MCP session fails during startup", async () => {
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"test-key",
			async () => {
				throw new Error("private startup detail");
			},
		);
		handles.push(handle);

		const result = await initialize(serverPort(handle));
		expect(result.statusCode).toBe(500);
		expect(result.body).toContain('"outcome":"terminal_failure"');
		expect(result.body).not.toContain("private startup detail");
	});

	it("rejects a DNS-rebinding Host header and closes active sessions", async () => {
		const { handle, port } = await startTestServer();
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0" },
					{ host: "attacker.example" },
				)
			).statusCode,
		).toBe(403);
		const initialized = await initialize(port);
		expect(initialized.statusCode).toBe(200);
		const stream = await openStream(port, {
			"mcp-session-id": String(initialized.headers["mcp-session-id"]),
		});
		await expect(handle.close()).resolves.toBeUndefined();
		await expect(stream.ended).resolves.toBeUndefined();
		expect(handle.server.listening).toBe(false);
	});

	it("rejects non-loopback startup without a bearer token", async () => {
		await expect(
			startStreamableHttpServer(
				{ transport: "http", host: "192.0.2.1", port: 3000 },
				"test-key",
				createMcpServer,
			),
		).rejects.toThrow("HEVY_MCP_HTTP_BEARER_TOKEN");
	});
});

