	return (
		expected.byteLength === actual.byteLength &&
		timingSafeEqual(expected, actual)
	);
}

function aggregateErrors(errors: unknown[], message: string): unknown {
	if (errors.length === 1) return errors[0];
	return new AggregateError(errors, message);
}

export function isHttpHostAllowed(host: string): boolean {
	return isLoopbackHost(host);
}

export async function startStreamableHttpServer(
	options: NodeCliOptions,
	apiKey: string,
	createMcpServer: McpServerFactory,
	configOverrides: Partial<HttpAdmissionConfig> = {},
): Promise<HttpServerHandle> {
	const config = resolveHttpAdmissionConfig(configOverrides);
	const wildcard =
		options.host === "0.0.0.0" ||
		options.host === "::" ||
		options.host === "[::]";
	const loopback = isLoopbackHost(options.host);
	const bearerToken = process.env[HTTP_BEARER_TOKEN];
	if (!loopback && !bearerToken) {
		throw new Error(
			`Non-loopback HTTP mode requires ${HTTP_BEARER_TOKEN} to protect the shared Hevy account.`,
		);
	}

	const sessions = new Map<string, HttpSession>();
	const initializationControllers = new Set<AbortController>();
	const cleanupErrors: unknown[] = [];
	let shuttingDown = false;
	const server = createServer((request, response) => {
		void handleRequest(request, response).catch((error: unknown) => {
			if (response.headersSent) {
				if (!response.writableEnded) response.destroy();
				return;
			}
			if (error instanceof HttpRequestError) {
				writeJson(response, error.statusCode, error.message);
				return;
			}
			console.error(`HTTP request failed: ${safeDiagnostic(error)}`);
			writeExecutionJson(response, 500, "Internal server error.", error);
		});
	});

	function armIdleTimer(session: HttpSession): void {
		if (session.closed) return;
		if (session.idleTimer) clearTimeout(session.idleTimer);
		session.idleTimer = setTimeout(() => {
			void closeSession(session).catch((error: unknown) => {
				cleanupErrors.push(error);
			});
		}, config.idleTimeoutMs);
		session.idleTimer.unref?.();
	}

	async function closeSession(
		session: HttpSession,
		failureCategory?: "connect_failure" | "startup_failure" | "unknown",
	): Promise<void> {
		if (session.closed) return;
		session.closed = true;
		if (session.idleTimer) {
			clearTimeout(session.idleTimer);
			session.idleTimer = undefined;
		}
		for (const [id, current] of sessions) {
			if (current === session) sessions.delete(id);
		}
		for (const response of session.responses) {
			if (!response.writableEnded) response.destroy();
		}
		// The SDK transport closes response streams, but its stateful close path
		// does not abort the request signal already handed to MCP handlers. Abort
		// the session-owned lifecycle signal first so active Hevy calls stop too.
		session.lifecycleController.abort(
			new DOMException("MCP session closed", "AbortError"),
		);

		const results = await Promise.allSettled([
			Promise.resolve().then(() => session.transport.close()),
			Promise.resolve().then(() => session.server.close()),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		const succeeded = errors.length === 0;
		recordMcpSessionTermination(
			failureCategory && succeeded
				? failureCategory
				: resolveSessionTerminationCategory(succeeded, session.context),
			session.context,
		);
		if (errors.length > 0) {
			throw aggregateErrors(errors, "MCP session cleanup failed.");
		}
	}

	async function closeUnregistered(
		transport: HttpTransport,
		mcpServer: OwnedMcpServer | undefined,
	): Promise<void> {
		const results = await Promise.allSettled([
			Promise.resolve().then(() => transport.close()),
			...(mcpServer ? [Promise.resolve().then(() => mcpServer.close())] : []),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		if (errors.length > 0) throw aggregateErrors(errors, "MCP cleanup failed.");
		return;
	}

	function trackSessionResponse(
		session: HttpSession,
		response: ServerResponse,
	): void {
		session.responses.add(response);
		response.once("close", () => {
			session.responses.delete(response);
			// A destroyed response means the client disconnected before the
			// exchange completed. The SDK does not expose a request-scoped signal
			// for this transport, so evict and close the whole session rather than
			// leaving an aborted session reusable or poisoning future requests.
			if (!response.writableEnded && !session.closed) {
				void closeSession(session).catch((error: unknown) => {
					cleanupErrors.push(error);
				});
			}
		});
	}

	async function handleRequest(
		request: IncomingMessage,
		response: ServerResponse,
	): Promise<void> {
		if (request.url?.split("?", 1)[0] !== MCP_PATH) {
			writeJson(response, 404, "Not found");
			return;
		}
		if (
			!validateHostHeader(
				request,
				hostNamesFor(options),
				expectedPort(options, server),
				wildcard,
			)
		) {
			writeJson(response, 403, "Invalid Host header");
			return;
		}
		if (!loopback && !isBearerAuthorized(request, bearerToken)) {
			writeJson(response, 401, "Authorization required");
			return;
		}

		const body =
			request.method === "POST"
				? await readBody(request, config.bodyTimeoutMs)
				: undefined;
		const initializing = request.method === "POST" && isInitializeRequest(body);
		const sessionHeader = request.headers["mcp-session-id"];
		const sessionId =
			typeof sessionHeader === "string" ? sessionHeader : undefined;

		if (initializing) {
			if (shuttingDown) {
				writeJson(
					response,
					503,
					"HTTP server is shutting down. Retry shortly.",
				);
				return;
			}
			if (
				sessions.size + initializationControllers.size >=
				config.maxSessions
			) {
				writeJson(
					response,
					429,
					"MCP session capacity reached. Retry after an existing session closes.",
				);
				return;
			}
			if (initializationControllers.size >= config.maxInitializing) {
				writeJson(
					response,
					503,
					"MCP server is busy initializing sessions. Retry shortly.",
				);
				return;
			}
			if (sessionId) {
				writeJson(
					response,
					400,
					"Initialization must not include Mcp-Session-Id.",
				);
				return;
			}
			const context = createMcpSessionContext(body, "http");
			recordMcpSessionStart(body, "http", context);
			let session: HttpSession | undefined;
			let mcpServer: OwnedMcpServer | undefined;
			let connected = false;
			const lifecycleController = new AbortController();
			initializationControllers.add(lifecycleController);
			const transport = new NodeStreamableHTTPServerTransport({
				sessionIdGenerator: randomUUID,
				onsessioninitialized: (id) => {
					if (!session) return;
					if (shuttingDown) {
						void closeSession(session).catch((error: unknown) => {
							cleanupErrors.push(error);
						});
						return;
					}
					sessions.set(id, session);
					armIdleTimer(session);
				},
			});
			transport.onclose = () => {
				if (session) {
					void closeSession(session).catch((error: unknown) => {
						cleanupErrors.push(error);
					});
				}
			};
			try {
				mcpServer = await createMcpServer({
					apiKey,
					lifecycleSignal: lifecycleController.signal,
				});
				if (shuttingDown) {
					await closeUnregistered(transport, mcpServer);
					return;
				}
				session = {
					transport,
					server: mcpServer,
					context,
					lifecycleController,
					responses: new Set(),
					closed: false,
				};
				await mcpServer.connect(transport);
				connected = true;
				if (shuttingDown) {
					await closeSession(session);
					return;
				}
				trackSessionResponse(session, response);
				await runWithMcpSessionContext(context, () =>
					transport.handleRequest(request, response, body),
				);
			} catch (error) {
				lifecycleController.abort(
					new DOMException("MCP session startup failed", "AbortError"),
				);
				console.error(`HTTP session request failed: ${safeDiagnostic(error)}`);
				let cleanupError: unknown;
				try {
					if (session) {
						await closeSession(
							session,
							connected ? "unknown" : "connect_failure",
						);
					} else {
						await closeUnregistered(transport, mcpServer);
						recordMcpSessionTermination("startup_failure", context);
					}
				} catch (cleanupFailure) {
					cleanupError = cleanupFailure;
					if (!session) recordMcpSessionTermination("unknown", context);
				}
				if (cleanupError) {
					console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
				}
				if (!response.writableEnded && !shuttingDown)
					writeExecutionJson(response, 500, "Internal server error.", error);
			} finally {
				initializationControllers.delete(lifecycleController);
			}
			return;
		}

		if (!sessionId) {
			writeJson(response, 400, "Mcp-Session-Id header is required.");
			return;
		}
		const session = sessions.get(sessionId);
		if (!session) {
			writeJson(response, 404, "Unknown Mcp-Session-Id.");
			return;
		}
		armIdleTimer(session);
		if (request.method !== "DELETE") {
			trackSessionResponse(session, response);
		}
		await runWithMcpSessionContext(session.context, () =>
			session.transport.handleRequest(request, response, body),
		);
		if (request.method === "DELETE" && !session.closed) {
			try {
				await closeSession(session);
			} catch (error: unknown) {
				cleanupErrors.push(error);
			}
		}
	}

	await new Promise<void>((resolve, reject) => {
		server.once("error", reject);
		server.listen(options.port, options.host, () => {
			server.removeListener("error", reject);
			resolve();
		});
	});

	let closePromise: Promise<void> | undefined;
	return {
		server,
		close: () => {
			if (closePromise) return closePromise;
			closePromise = (async () => {
				shuttingDown = true;
				for (const controller of initializationControllers) {
					controller.abort(
						new DOMException("HTTP server is shutting down", "AbortError"),
					);
				}
				const sessionsToClose = [...sessions.values()];
				const results = await Promise.allSettled([
					...sessionsToClose.map((session) => closeSession(session)),
					closeServer(server),
				]);
				sessions.clear();
				const errors = [
					...cleanupErrors,
					...results.flatMap((result) =>
						result.status === "rejected" ? [result.reason] : [],
					),
				];
				if (errors.length > 0) {
					throw aggregateErrors(errors, "HTTP server cleanup failed.");
				}
			})();
			return closePromise;
		},
	};
}

		const result = await new Promise<HttpResult>((resolve, reject) => {
			const client = request(
				{
					host: "127.0.0.1",
					port: serverPort(handle),
					path: "/mcp",
					method: "POST",
				},
				(response) => {
					const chunks: Buffer[] = [];
					response.on("data", (chunk: Buffer) => chunks.push(chunk));
					response.once("end", () =>
						resolve({
							statusCode: response.statusCode,
							headers: response.headers,
							body: Buffer.concat(chunks).toString("utf8"),
						}),
					);
				},
			);
			client.once("error", reject);
			client.flushHeaders();
		});
		expect(result.statusCode).toBe(408);
		expect(result.body).toBe('{"error":"Request body timed out."}');
	});

	it("supports initialize, tools/list, and a mocked tools/call", async () => {
		const { port } = await startTestServer();
		const initialized = await initialize(port);
		expect(initialized.statusCode).toBe(200);
		const sessionId = initialized.headers["mcp-session-id"];
		expect(typeof sessionId).toBe("string");

		const headers = { "mcp-session-id": String(sessionId) };
		const listed = await call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 2,
				method: "tools/list",
				params: {},
			},
			headers,
		);
		expect(listed.statusCode).toBe(200);
		expect(JSON.stringify(jsonBody(listed))).toContain("mock-tool");

		const called = await call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 3,
				method: "tools/call",
				params: { name: "mock-tool", arguments: {} },
			},
			headers,
		);
		expect(called.statusCode).toBe(200);
		expect(JSON.stringify(jsonBody(called))).toContain("mock result");
	});

	it("keeps two clients isolated and routes unknown sessions safely", async () => {
		const { port } = await startTestServer();
		const first = await initialize(port);
		const second = await initialize(port);
		const firstSession = String(first.headers["mcp-session-id"]);
		const secondSession = String(second.headers["mcp-session-id"]);
		expect(firstSession).not.toBe(secondSession);

		const firstList = await call(
			port,
			"POST",
			{ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} },
			{ "mcp-session-id": firstSession },
		);
		const secondList = await call(
			port,
			"POST",
			{ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} },
			{ "mcp-session-id": secondSession },
		);
		expect(firstList.statusCode).toBe(200);
		expect(secondList.statusCode).toBe(200);

		expect((await call(port, "POST", { jsonrpc: "2.0" })).statusCode).toBe(400);
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0", id: 4, method: "tools/list" },
					{ "mcp-session-id": "missing-session" },
				)
			).statusCode,
		).toBe(404);
	});

	it("removes a session on DELETE", async () => {
		const { port } = await startTestServer();
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const deleted = await call(port, "DELETE", undefined, {
			"mcp-session-id": sessionId,
		});
		expect(deleted.statusCode).toBe(200);
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0", id: 2, method: "tools/list" },
					{ "mcp-session-id": sessionId },
				)
			).statusCode,
		).toBe(404);
	});

	it("evicts a session after a disconnected request", async () => {
		const { port, toolStarted, releaseTool } =
			await startDisconnectTestServer();
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const payload = JSON.stringify({
			jsonrpc: "2.0",
			id: 2,
			method: "tools/call",
			params: { name: "mock-tool", arguments: {} },
		});
		const disconnected = request({
			host: "127.0.0.1",
			port,
			path: "/mcp",
			method: "POST",
			headers: {
				Accept: "application/json, text/event-stream",
				"Content-Type": "application/json",
				"mcp-session-id": sessionId,
			},
		});
		disconnected.once("error", () => {});
		disconnected.end(payload);
		await toolStarted;
		disconnected.destroy();

		await vi.waitFor(async () => {
			const aftermath = await call(
				port,
				"POST",
				{ jsonrpc: "2.0", id: 3, method: "tools/list", params: {} },
				{ "mcp-session-id": sessionId },
			);
			expect(aftermath.statusCode).toBe(404);
		});
		releaseTool();
	});

	it("aborts active session execution when DELETE closes the transport", async () => {
		let sessionSignal: AbortSignal | undefined;
		let markStarted!: () => void;
		const toolStarted = new Promise<void>((resolve) => {
			markStarted = resolve;
		});
		const createAbortAwareServer = async ({
			lifecycleSignal,
		}: {
			apiKey: string;
			lifecycleSignal?: AbortSignal;
		}) => {
			sessionSignal = lifecycleSignal;
			const server = new McpServer({ name: "abort-aware", version: "1.0.0" });
			server.registerTool(
				"mock-tool",
				{ description: "A mocked tool" },
				async () => {
					markStarted();
					await new Promise<void>((resolve) =>
						lifecycleSignal?.addEventListener("abort", () => resolve(), {
							once: true,
						}),
					);
					return { content: [{ type: "text", text: "aborted" }] };
				},
			);
			return server;
		};
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"test-key",
			createAbortAwareServer,
		);
		handles.push(handle);
		const port = serverPort(handle);
		const initialized = await initialize(port);
		const sessionId = String(initialized.headers["mcp-session-id"]);
		const pendingCall = call(
			port,
			"POST",
			{
				jsonrpc: "2.0",
				id: 2,
				method: "tools/call",
				params: { name: "mock-tool", arguments: {} },
			},
			{ "mcp-session-id": sessionId },
		).catch(() => undefined);
		await toolStarted;
		await expect(
			call(port, "DELETE", undefined, { "mcp-session-id": sessionId }),
		).resolves.toMatchObject({ statusCode: 200 });
		expect(sessionSignal?.aborted).toBe(true);
		void pendingCall;
	});

	it("requires bearer authentication for wildcard binds", async () => {
		process.env.HEVY_MCP_HTTP_BEARER_TOKEN = "http-test-token";
		try {
			const { port } = await startTestServer("0.0.0.0");
			expect((await initialize(port)).statusCode).toBe(401);
			const authorized = await initialize(port, {
				authorization: "Bearer http-test-token",
			});
			expect(authorized.statusCode).toBe(200);
		} finally {
			delete process.env.HEVY_MCP_HTTP_BEARER_TOKEN;
		}
	});

	it("returns safe 400/413 responses for malformed and oversized bodies", async () => {
		const { port } = await startTestServer();
		// Send malformed JSON directly because the helper serializes valid bodies.
		const invalid = await new Promise<HttpResult>((resolve, reject) => {
			const client = request(
				{ host: "127.0.0.1", port, path: "/mcp", method: "POST" },
				(response) => {
					const chunks: Buffer[] = [];
					response.on("data", (chunk: Buffer) => chunks.push(chunk));
					response.once("end", () =>
						resolve({
							statusCode: response.statusCode,
							headers: response.headers,
							body: Buffer.concat(chunks).toString("utf8"),
						}),
					);
				},
			);
			client.once("error", reject);
			client.end("not-json");
		});
		expect(invalid.statusCode).toBe(400);
		expect(invalid.body).not.toContain("not-json");

		const oversized = await call(port, "POST", "x".repeat(1_048_577));
		expect(oversized.statusCode).toBe(413);
	});

	it("returns structured errors when an MCP session fails during startup", async () => {
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"test-key",
			async () => {
				throw new Error("private startup detail");
			},
		);
		handles.push(handle);

		const result = await initialize(serverPort(handle));
		expect(result.statusCode).toBe(500);
		expect(result.body).toContain('"outcome":"terminal_failure"');
		expect(result.body).not.toContain("private startup detail");
	});

	it("rejects a DNS-rebinding Host header and closes active sessions", async () => {
		const { handle, port } = await startTestServer();
		expect(
			(
				await call(
					port,
					"POST",
					{ jsonrpc: "2.0" },
					{ host: "attacker.example" },
				)
			).statusCode,
		).toBe(403);
		const initialized = await initialize(port);
		expect(initialized.statusCode).toBe(200);
		const stream = await openStream(port, {
			"mcp-session-id": String(initialized.headers["mcp-session-id"]),
		});
		await expect(handle.close()).resolves.toBeUndefined();
		await expect(stream.ended).resolves.toBeUndefined();
		expect(handle.server.listening).toBe(false);
	});

	it("rejects non-loopback startup without a bearer token", async () => {
		await expect(
			startStreamableHttpServer(
				{ transport: "http", host: "192.0.2.1", port: 3000 },
				"test-key",
				createMcpServer,
			),
		).rejects.toThrow("HEVY_MCP_HTTP_BEARER_TOKEN");
	});
});

import { request, type Server } from "node:http";
import { McpServer } from "@modelcontextprotocol/server";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
	resolveHttpAdmissionConfig,
	startStreamableHttpServer,
} from "./streamable-http.js";

const createMcpServer = async () => {
	const server = new McpServer({ name: "test-server", version: "1.0.0" });
	server.registerTool(
		"mock-tool",
		{ description: "A mocked tool" },
		async () => ({ content: [{ type: "text", text: "mock result" }] }),
	);
	return server;
};

const handles: Array<{ close(): Promise<void> }> = [];

afterEach(async () => {
	await Promise.all(handles.splice(0).map((handle) => handle.close()));
});

interface HttpResult {
	statusCode?: number;
	headers: Record<string, string | string[] | undefined>;
	body: string;
}

function openStream(
	port: number,
	headers: Record<string, string>,
): Promise<{ ended: Promise<void> }> {
	return new Promise((resolve, reject) => {
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method: "GET",
				headers: { Accept: "text/event-stream", ...headers },
			},
			(response) => {
				const ended = new Promise<void>((finish) => {
					response.once("end", finish);
					response.once("close", finish);
				});
				resolve({ ended });
			},
		);
		client.once("error", reject);
		client.end();
	});
}

function call(
	port: number,
	method: string,
	body?: unknown,
	extraHeaders: Record<string, string> = {},
): Promise<HttpResult> {
	return new Promise((resolve, reject) => {
		const payload = body === undefined ? undefined : JSON.stringify(body);
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method,
				headers: {
					Accept: "application/json, text/event-stream",
					...(payload ? { "Content-Type": "application/json" } : {}),
					...extraHeaders,
				},
			},
			(response) => {
				const chunks: Buffer[] = [];
				response.on("data", (chunk: Buffer) => chunks.push(chunk));
				response.once("end", () =>
					resolve({
						statusCode: response.statusCode,
						headers: response.headers,
						body: Buffer.concat(chunks).toString("utf8"),
					}),
				);
			},
		);
		client.once("error", reject);
		if (payload) client.write(payload);
		client.end();
	});
}

function serverPort(handle: { server: Server }): number {
	const address = handle.server.address();
	if (!address || typeof address === "string") throw new Error("No address");
	return address.port;
}

function jsonBody(result: HttpResult): Record<string, unknown> {
	const json = result.body.startsWith("event:")
		? result.body
				.split("\n")
				.filter((line) => line.startsWith("data:"))
