	const handle = await startStreamableHttpServer(
		{ transport: "http", host, port: 0 },
		"test-key",
		createMcpServer,
	);
	handles.push(handle);
	return { handle, port: serverPort(handle) };
}

async function startDisconnectTestServer() {
	let releaseTool!: () => void;
	let markStarted!: () => void;
