597						}
598					} catch (cleanupFailure) {
599						cleanupError = cleanupFailure;
600						if (!session) recordMcpSessionTermination("unknown", context);
601					}
602					if (cleanupError) {
603						console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
604					}
605					if (!response.writableEnded && !shuttingDown)
