607				} finally {
608					initializationControllers.delete(lifecycleController);
609				}
610				return;
611			}
612	
613			if (!sessionId) {
614				writeJson(response, 400, "Mcp-Session-Id header is required.");
615				return;
616			}
617			const session = sessions.get(sessionId);
618			if (!session) {
619				writeJson(response, 404, "Unknown Mcp-Session-Id.");
620				return;
621			}
622			armIdleTimer(session);
623			if (request.method !== "DELETE") {
624				trackSessionResponse(session, response);
625			}
626			await runWithMcpSessionContext(session.context, () =>
627				session.transport.handleRequest(request, response, body),
628			);
