630				try {
631					await closeSession(session);
632				} catch (error: unknown) {
633					cleanupErrors.push(error);
634				}
635			}
636		}
637	
638		await new Promise<void>((resolve, reject) => {
639			server.once("error", reject);
640			server.listen(options.port, options.host, () => {
641				server.removeListener("error", reject);
642				resolve();
643			});
644		});
645	
646		let closePromise: Promise<void> | undefined;
647		return {
648			server,
649			close: () => {
650				if (closePromise) return closePromise;
651				closePromise = (async () => {
652					shuttingDown = true;
653					for (const controller of initializationControllers) {
654						controller.abort(
655							new DOMException("HTTP server is shutting down", "AbortError"),
656						);
657					}
658					const sessionsToClose = [...sessions.values()];
659					const results = await Promise.allSettled([
660						...sessionsToClose.map((session) => closeSession(session)),
661						closeServer(server),
662					]);
663					sessions.clear();
664					const errors = [
665						...cleanupErrors,
666						...results.flatMap((result) =>
667							result.status === "rejected" ? [result.reason] : [],
668						),
669					];
670					if (errors.length > 0) {
671						throw aggregateErrors(errors, "HTTP server cleanup failed.");
672					}
673				})();
674				return closePromise;
675			},
676		};
677	}

