edits.oldText:
function readBody(
	request: IncomingMessage,
	timeoutMs: number,
): Promise<unknown> {
	return new Promise((resolve, reject) => {
		let size = 0;
		let settled = false;
		const chunks: Buffer[] = [];
		const timer = setTimeout(() => {
			if (settled) return;
			settled = true;
			cleanup();
			request.resume();
			reject(new HttpRequestError(408, "Request body timed out."));
		}, timeoutMs);
		const cleanup = () => {
			clearTimeout(timer);
			request.removeListener("data", onData);
			request.removeListener("error", onError);
			request.removeListener("end", onEnd);
		};
		const settle = (callback: () => void) => {
			if (settled) return;
			settled = true;
			cleanup();
			callback();
		};
		const onData = (chunk: Buffer | string) => {
			const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
			size += buffer.byteLength;
			if (size > MAX_BODY_BYTES) {
				settle(() => {
					request.resume();
					reject(new HttpRequestError(413, "Request body is too large."));
				});
				return;
			}
			if (!settled) chunks.push(buffer);
		};
		const onError = (error: Error) => settle(() => reject(error));
		const onEnd = () =>
			settle(() => {
				try {
					const raw = Buffer.concat(chunks).toString("utf8");
					resolve(raw.length === 0 ? undefined : JSON.parse(raw));
				} catch {
					reject(new HttpRequestError(400, "Request body must be valid JSON."));
				}
			});
		request.on("data", onData);
		request.once("error", onError);
		request.once("end", onEnd);
	});
}

