232	function readBody(
233		request: IncomingMessage,
234		timeoutMs: number,
235		signal?: AbortSignal,
236	): Promise<unknown> {
237		return new Promise((resolve, reject) => {
238			let size = 0;
239			let settled = false;
240			const chunks: Buffer[] = [];
241			let timer: ReturnType<typeof setTimeout> | undefined;
242			const removeErrorListenerAfterDrain = () => {
243				request.removeListener("error", onError);
244			};
245			const cleanup = (retainErrorListener = false) => {
246				if (timer) clearTimeout(timer);
247				request.removeListener("data", onData);
248				request.removeListener("end", onEnd);
249				if (retainErrorListener) {
250					request.once("close", removeErrorListenerAfterDrain);
251				} else {
252					request.removeListener("error", onError);
253				}
254				signal?.removeEventListener("abort", onAbort);
255			};
256			const settle = (callback: () => void, retainErrorListener = false) => {
257				if (settled) return;
258				settled = true;
259				cleanup(retainErrorListener);
260				callback();
261			};
262			const rejectAndDrain = (error: HttpRequestError) => {
263				if (settled) return;
264				settled = true;
265				cleanup(true);
266				request.resume();
267				reject(error);
268			};
269			const onData = (chunk: Buffer | string) => {
270				const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
271				size += buffer.byteLength;
272				if (size > MAX_BODY_BYTES) {
273					rejectAndDrain(new HttpRequestError(413, "Request body is too large."));
274					return;
275				}
276				if (!settled) chunks.push(buffer);
277			};
278			const onError = (error: Error) => settle(() => reject(error));
279			const onAbort = () =>
280				rejectAndDrain(
281					new HttpRequestError(
282						503,
283						"HTTP server is shutting down. Retry shortly.",
284					),
285				);
286			const onEnd = () =>
287				settle(() => {
288					try {
289						const raw = Buffer.concat(chunks).toString("utf8");
290						resolve(raw.length === 0 ? undefined : JSON.parse(raw));
291					} catch {
292						reject(new HttpRequestError(400, "Request body must be valid JSON."));
293					}
294				});
295			request.on("data", onData);
296			request.once("error", onError);
297			request.once("end", onEnd);
298			signal?.addEventListener("abort", onAbort, { once: true });
299			timer = setTimeout(() => {
300				rejectAndDrain(new HttpRequestError(408, "Request body timed out."));
301			}, timeoutMs);
302			timer.unref?.();
303			if (signal?.aborted) onAbort();
304		});
305	}
