import type { ToolAnnotations } from "@modelcontextprotocol/server";
import { z } from "zod";
import type {
	HevyToolFeature,
	McpToolOperation,
} from "../utils/tool-taxonomy.js";
import { hevyToolDefinitions } from "./register.js";

/** The MCP revision used by the initial, deliberately bounded contract matrix. */
export const CONTRACT_MATRIX_PROTOCOL_VERSION = "2025-11-25" as const;

export interface ToolCapabilityDescriptor<
	TInput extends z.ZodTypeAny = z.ZodTypeAny,
	TOutput extends z.ZodTypeAny = z.ZodTypeAny,
> {
	readonly name: string;
	readonly feature: HevyToolFeature;
	readonly kind: "read";
	readonly operation: McpToolOperation;
	readonly description: string;
	readonly inputSchema: TInput;
	readonly outputSchema: TOutput;
	readonly annotations: ToolAnnotations;
}

export type ToolCapabilityCatalog = Readonly<
	Record<string, ToolCapabilityDescriptor>
>;

type ReadToolDefinition = Extract<
	(typeof hevyToolDefinitions)[number],
	{ readonly kind: "read" }
>;

function createCapabilityDescriptor(
	definition: ReadToolDefinition,
): ToolCapabilityDescriptor {
	return {
		name: definition.name,
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
		description: definition.description,
		inputSchema: z.strictObject(definition.inputSchema),
		outputSchema: z.object(definition.outputSchema),
		annotations: definition.annotations,
	};
}

const readCapabilityDescriptors = hevyToolDefinitions
	.filter(
		(definition): definition is ReadToolDefinition =>
			definition.kind === "read",
	)
	.map(createCapabilityDescriptor);

export const toolCapabilityCatalog: ToolCapabilityCatalog = Object.fromEntries(
	readCapabilityDescriptors.map((descriptor) => [descriptor.name, descriptor]),
);

/** Production-owned descriptor for the first contract-matrix capability. */
export const getWorkoutsCapabilityDescriptor =
	toolCapabilityCatalog["get-workouts"];
if (!getWorkoutsCapabilityDescriptor) {
	throw new Error("Missing production get-workouts capability descriptor");
}

import type { HevyClient } from "@hevy-mcp/hevy-client";
import { getWorkoutsCapabilityDescriptor } from "@hevy-mcp/core";

export const deterministicWorkout = {
	id: "workout-1",
	title: "Contract fixture",
	start_time: "2025-01-01T10:00:00Z",
	end_time: "2025-01-01T10:30:00Z",
	exercises: [],
};

/** Minimal generated-client result consumed by the production get-workouts tool. */
export const deterministicGetWorkoutsResult = {
	workouts: [deterministicWorkout],
	page_count: 1,
};

/** Valid structured output, parsed with the production capability schema. */
export const validGetWorkoutsOutput =
	getWorkoutsCapabilityDescriptor.outputSchema.parse({
		workouts: [
			{
				id: "workout-1",
				title: "Contract fixture",
				start_time: "2025-01-01T10:00:00Z",
				end_time: "2025-01-01T10:30:00Z",
				duration: "0h 30m 0s",
				exercise_count: 0,
				set_count: 0,
			},
		],
		page: 1,
		page_count: 1,
		has_next_page: false,
	});

/** Deterministic client shared by every adapter case in the initial matrix. */
export function createDeterministicHevyClient(): HevyClient {
	return {
		getWorkouts: async () => deterministicGetWorkoutsResult,
		getUserInfo: async () => ({ data: { id: "contract-user" } }),
	} as unknown as HevyClient;
}

import { InMemoryTransport, McpServer } from "@modelcontextprotocol/server";
import { Client } from "@modelcontextprotocol/client";
import {
	createHevyMcpServer,
	type CreateHevyMcpServerOptions,
} from "@hevy-mcp/core";
import {
	CONTRACT_MATRIX_PROTOCOL_VERSION,
	getWorkoutsCapabilityDescriptor,
} from "@hevy-mcp/core";
import { startStreamableHttpServer } from "../../packages/node/src/utils/streamable-http.js";
import { createWorkerHandler } from "../../packages/worker/src/worker.js";
import {
	createDeterministicHevyClient,
	validGetWorkoutsOutput,
} from "./fixtures.js";
import { afterEach, describe, expect, it, vi } from "vitest";

const minimalInput = getWorkoutsCapabilityDescriptor.inputSchema.parse({
	page: 1,
}) as Record<string, unknown>;

function assertGetWorkoutsResult(result: unknown): void {
	if (typeof result !== "object" || result === null) {
		throw new Error("Expected MCP tool result object");
	}
	const response = result as {
		content?: unknown;
		structuredContent?: unknown;
	};
	if (!Array.isArray(response.content)) {
		throw new Error("Expected MCP tool content array");
	}
	const structured = getWorkoutsCapabilityDescriptor.outputSchema.parse(
		response.structuredContent,
	) as { workouts: readonly unknown[] };
	expect(structured).toEqual(validGetWorkoutsOutput);
	const firstContent = response.content[0];
	if (
		typeof firstContent !== "object" ||
		firstContent === null ||
		!("type" in firstContent) ||
		firstContent.type !== "text" ||
		!("text" in firstContent) ||
		typeof firstContent.text !== "string"
	) {
		throw new Error("Expected text content in MCP tool response");
	}
	expect(JSON.parse(firstContent.text)).toEqual(structured.workouts);
}

function parseStreamableResponse(text: string): Record<string, unknown> {
	const data = text
		.split("\n")
		.find((line) => line.startsWith("data: "))
		?.slice("data: ".length);
	if (!data) throw new Error(`Missing MCP SSE data: ${text}`);
	return JSON.parse(data) as Record<string, unknown>;
}

async function postNodeMcp(
	url: string,
	body: unknown,
	extraHeaders: Record<string, string> = {},
): Promise<{ response: Response; payload: Record<string, unknown> }> {
	const response = await fetch(url, {
		method: "POST",
		headers: {
			accept: "application/json, text/event-stream",
			"content-type": "application/json",
			...extraHeaders,
		},
		body: JSON.stringify(body),
	});
	return { response, payload: parseStreamableResponse(await response.text()) };
}

function mcpRequest(body: unknown): Request {
	return new Request("https://contract-matrix.example/mcp", {
		method: "POST",
		headers: {
			accept: "application/json, text/event-stream",
			"content-type": "application/json",
			authorization: "Bearer contract-test-key",
		},
		body: JSON.stringify(body),
	});
}

async function postWorkerMcp(
	handler: ReturnType<typeof createWorkerHandler>,
	body: unknown,
): Promise<{ response: Response; payload: Record<string, unknown> }> {
	const response = await handler(mcpRequest(body), {});
	return { response, payload: parseStreamableResponse(await response.text()) };
}

function initializeBody() {
	return {
		jsonrpc: "2.0",
		id: 1,
		method: "initialize",
		params: {
			protocolVersion: CONTRACT_MATRIX_PROTOCOL_VERSION,
			capabilities: {},
			clientInfo: { name: "contract-matrix", version: "1.0.0" },
		},
	};
}

describe("initial runtime contract matrix", () => {
	let inMemoryServer: McpServer | undefined;
	let inMemoryClient: Client | undefined;

	afterEach(async () => {
		await Promise.all([inMemoryClient?.close(), inMemoryServer?.close()]);
		inMemoryClient = undefined;
		inMemoryServer = undefined;
	});

	it("runs the descriptor case through Core in-memory", async () => {
		inMemoryServer = createHevyMcpServer({
			createClient: () => createDeterministicHevyClient(),
		});
		inMemoryClient = new Client({
			name: "contract-matrix-client",
			version: "1",
		});
		const [clientTransport, serverTransport] =
			InMemoryTransport.createLinkedPair();
		await Promise.all([
			inMemoryServer.connect(serverTransport),
			inMemoryClient.connect(clientTransport),
		]);

		const listed = await inMemoryClient.listTools();
		const listedTool = listed.tools.find(
			({ name }) => name === getWorkoutsCapabilityDescriptor.name,
		);
		expect(listedTool).toBeDefined();
		expect(listedTool?.description).toBe(
			getWorkoutsCapabilityDescriptor.description,
		);

		const result = await inMemoryClient.callTool({
			name: getWorkoutsCapabilityDescriptor.name,
			arguments: minimalInput,
		});
		assertGetWorkoutsResult(result);
	});

	it("runs the descriptor case through the stateful Node HTTP adapter", async () => {
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"contract-test-key",
			async () =>
				createHevyMcpServer({
					createClient: () => createDeterministicHevyClient(),
				}),
		);
		try {
			const address = handle.server.address();
			if (!address || typeof address === "string") throw new Error("No port");
			const url = `http://127.0.0.1:${address.port}/mcp`;
			const initialized = await postNodeMcp(url, initializeBody());
			expect(initialized.response.status).toBe(200);
			const sessionId = initialized.response.headers.get("mcp-session-id");
			expect(sessionId).toEqual(expect.any(String));

			const listed = await postNodeMcp(
				url,
				{ jsonrpc: "2.0", id: 2, method: "tools/list" },
				{ "mcp-session-id": sessionId! },
			);
			expect(listed.response.status).toBe(200);
			const tools = listed.payload.result as {
				tools: Array<{ name: string }>;
			};
			expect(
				tools.tools.some(
					({ name }) => name === getWorkoutsCapabilityDescriptor.name,
				),
			).toBe(true);

			const called = await postNodeMcp(
				url,
				{
					jsonrpc: "2.0",
					id: 3,
					method: "tools/call",
					params: {
						name: getWorkoutsCapabilityDescriptor.name,
						arguments: minimalInput,
					},
				},
				{ "mcp-session-id": sessionId! },
			);
			expect(called.response.status).toBe(200);
			assertGetWorkoutsResult(called.payload.result);
		} finally {
			await handle.close();
		}
	});

	it("runs the descriptor case through the stateless Worker handler", async () => {
		const createServer = vi.fn(
			(createClient: CreateHevyMcpServerOptions["createClient"]) =>
				createHevyMcpServer({ createClient }),
		);
		const handler = createWorkerHandler({
			createValidationClient: () => createDeterministicHevyClient(),
			createRequestClient: () => createDeterministicHevyClient(),
			createServer,
		});

		const initialized = await postWorkerMcp(handler, initializeBody());
		expect(initialized.response.status).toBe(200);
		expect(initialized.response.headers.get("mcp-session-id")).toBeNull();

		const listed = await postWorkerMcp(handler, {
			jsonrpc: "2.0",
			id: 2,
			method: "tools/list",
		});
		expect(listed.response.status).toBe(200);
		expect(listed.response.headers.get("mcp-session-id")).toBeNull();
		const tools = listed.payload.result as { tools: Array<{ name: string }> };
		expect(
			tools.tools.some(
				({ name }) => name === getWorkoutsCapabilityDescriptor.name,
			),
		).toBe(true);

		const called = await postWorkerMcp(handler, {
			jsonrpc: "2.0",
			id: 3,
			method: "tools/call",
			params: {
				name: getWorkoutsCapabilityDescriptor.name,
				arguments: minimalInput,
			},
		});
		expect(called.response.status).toBe(200);
		expect(called.response.headers.get("mcp-session-id")).toBeNull();
		assertGetWorkoutsResult(called.payload.result);
		// A fresh server is composed for every request; no Worker session state is used.
		expect(createServer).toHaveBeenCalledTimes(3);
	});
});

import type {
	HevyClient,
	HevyExecutionOptions,
	HevyHttpError,
	HevyOperationSafety,
} from "@hevy-mcp/hevy-client";
import type { GetV1Workouts200, Workout } from "@hevy-mcp/hevy-client/types";
import {
	canonicalEndpointIdentity,
	expectedGet404Outcome,
	isHevyHttpError,
} from "@hevy-mcp/hevy-client";

export interface WorkoutsListInput {
	readonly page: number;
	readonly pageSize: number;
}

export interface WorkoutsListOutput {
	readonly items: Workout[];
	readonly page: number;
	readonly pageCount?: number;
	readonly expected404Outcome?: "end_of_list";
}

export type WorkoutsListAdapter = Pick<HevyClient, "getWorkouts">;

export interface WorkoutsListDescriptor {
	readonly id: "workouts.list";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const workoutsListDescriptor: WorkoutsListDescriptor = {
	id: "workouts.list",
	safety: "read",
};

export interface WorkoutsListOperation {
	readonly descriptor: WorkoutsListDescriptor;
	execute(
		input: WorkoutsListInput,
		options?: HevyExecutionOptions,
	): Promise<WorkoutsListOutput>;
}

function isExpectedEndOfList(error: unknown, page: number): boolean {
	return (
		page > 1 &&
		isHevyHttpError(error) &&
		canonicalEndpointIdentity(error.endpoint) === "/v1/workouts" &&
		expectedGet404Outcome(error.endpoint, error.method, error.status, page) ===
			"end_of_list"
	);
}

function normalizeWorkoutsPage(
	response: GetV1Workouts200,
	input: WorkoutsListInput,
): WorkoutsListOutput {
	if (response.page !== undefined && response.page !== input.page) {
		throw new Error(
			`Workouts page mismatch: requested page ${input.page} but received page ${response.page}`,
		);
	}
	return {
		items: response.workouts ?? [],
		page: response.page ?? input.page,
		pageCount: response.page_count,
	};
}

export function createWorkoutsListOperation(
	adapter: WorkoutsListAdapter,
): WorkoutsListOperation {
	return {
		descriptor: workoutsListDescriptor,
		async execute(input, options) {
			try {
				const params = { page: input.page, pageSize: input.pageSize };
				const response =
					options === undefined
						? await adapter.getWorkouts(params)
						: await adapter.getWorkouts(params, options);
				return normalizeWorkoutsPage(response, input);
			} catch (error) {
				if (isExpectedEndOfList(error, input.page)) {
					return {
						items: [],
						page: input.page,
						pageCount: undefined,
						expected404Outcome: "end_of_list",
					};
				}
				throw error;
			}
		},
	};
}

export function isWorkoutsListEndOfList(
	error: unknown,
	page: number,
): error is HevyHttpError {
	return isExpectedEndOfList(error, page);
}

