function normalizePositiveInteger(value: number | undefined, fallback: number) {
	return value === undefined || !Number.isFinite(value) || value <= 0
		? fallback
		: Math.max(1, Math.floor(value));
}

function normalizeMaxGetRetries(value: number | undefined) {
	return value === undefined || !Number.isFinite(value) || value < 0
		? MAX_GET_RETRIES
		: Math.floor(value);
}

function defaultSleep(
	milliseconds: number,
	signal?: AbortSignal,
): Promise<void> {
	if (signal?.aborted) {
		return Promise.reject(
			signal.reason ?? new DOMException("Operation canceled", "AbortError"),
		);
	}
	return new Promise((resolve, reject) => {
		let settled = false;
		let timer: ReturnType<typeof setTimeout> | undefined;
		const cleanup = () => {
			if (timer !== undefined) clearTimeout(timer);
			signal?.removeEventListener("abort", onAbort);
		};
		const resolveSleep = () => {
			if (settled) return;
			settled = true;
			cleanup();
			resolve();
		};
		const rejectSleep = (reason: unknown) => {
			if (settled) return;
			settled = true;
			cleanup();
			reject(reason);
		};
		const onAbort = () =>
			rejectSleep(
				signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
			);
		timer = setTimeout(resolveSleep, Math.max(0, milliseconds));
		signal?.addEventListener("abort", onAbort, { once: true });
		if (signal?.aborted) onAbort();
	});
}

function withTimeout<T>(
	operation: Promise<T>,
	timeoutMs: number,
	onTimeout: () => void,
	signal?: AbortSignal,
): Promise<T> {
	const promise = new Promise<T>((resolve, reject) => {
		let settled = false;
		const onAbort = () => {
			if (settled) return;
			settled = true;
			if (timer !== undefined) clearTimeout(timer);
			signal?.removeEventListener("abort", onAbort);
			reject(
				signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
			);
		};
		const timer = Number.isFinite(timeoutMs)
			? setTimeout(
					() => {
						if (settled) return;
						settled = true;
						signal?.removeEventListener("abort", onAbort);
						onTimeout();
						reject(new DOMException("Operation timed out", "TimeoutError"));
					},
					Math.max(0, timeoutMs),
				)
			: undefined;
		operation.then(
			(value) => {
				if (settled) return;
				settled = true;
				if (timer !== undefined) clearTimeout(timer);
				signal?.removeEventListener("abort", onAbort);
				resolve(value);
			},
			(error: unknown) => {
				if (settled) return;
				settled = true;
				if (timer !== undefined) clearTimeout(timer);
				signal?.removeEventListener("abort", onAbort);
				reject(error);
			},
		);
		if (signal?.aborted) onAbort();
		else signal?.addEventListener("abort", onAbort, { once: true });
	});
	return promise;
}

function getRequestContext(config: {
	method?: string;
	url?: string;
	params?: unknown;
}) {
	const method = (config.method ?? "GET").toUpperCase();
	const endpoint = canonicalEndpointIdentity(config.url ?? "");
	const page =
		config.params !== null &&
		typeof config.params === "object" &&
		"page" in config.params &&
		typeof config.params.page === "number"
			? config.params.page
			: undefined;
	return { method, endpoint, page };
}

