				run: scopeRun,
				finish: vi.fn(),
			}),
		});

		await expect(client.getUserInfo()).resolves.toEqual({});
		expect(scopeRun).toHaveBeenCalledOnce();
		expect(fetchMock).toHaveBeenCalledOnce();
