	it("marks supported read and later-page 404s as expected outcomes", async () => {
		const observations: Array<{
			outcome: string;
			expectedReason?: string;
		}> = [];
		const fetchMock = vi.fn().mockResolvedValue(response({}, 404));
		const client = createHevyClient({
			apiKey: "secret-key",
			fetch: fetchMock,
