	it("reports exhausted retries as terminal failures", async () => {
		const observations: Array<{
			outcome: string;
			code?: string;
		}> = [];
		const fetchMock = vi
			.fn()
			.mockResolvedValueOnce(response({}, 503))
			.mockResolvedValueOnce(response({}, 503));
		const client = createHevyClient({
			apiKey: "secret-key",
