			apiKey: "secret-key",
			fetch: fetchMock,
			maxGetRetries: 5,
		});

		await expect(
			client.createWorkout({ workout: {} } as never),
		).rejects.toMatchObject({
			commit_state: "unknown",
			safe_to_retry: false,
			operation_safety: "non-idempotent-write",
		});
